                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Explain consumer groups, prefetch/batch sizes to prevent memory flooding, asynchronous parallel processing with concurrency limits (p-limit), dead-letter exchanges (DLX) for failed messages, and graceful rebalance.',
                                        ],
                                        [
                                            'text' => 'How does zero-copy file streaming work in Node.js? Walk through serving large 5GB media files using fs.createReadStream with Range requests (HTTP 206 Partial Content) without spiking heap memory.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Parse \'Range\' header (bytes=start-end). Calculate Content-Range, Content-Length, set status 206. Create stream with {start, end} and pipe directly to response, letting libuv and OS handle buffer streaming.',
                                        ],
                                        [
                                            'text' => 'How do you implement the Circuit Breaker pattern in Node.js for external API dependencies (e.g. using Opossum)? Explain Closed, Open, and Half-Open states and fallback strategies.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Closed: normal requests. If failure rate exceeds threshold (e.g. 50%), breaker trips to Open (immediate fallback without network call). After resetTimeout, enters Half-Open (trial requests). Return degraded cache data as fallback.',
                                        ],
                                        [
                                            'text' => 'How do you architect a multipart file upload handler in Node.js that streams directly to AWS S3 (via @aws-sdk/lib-storage Upload) without buffering the file on local disk or in RAM?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use busboy or fastify-multipart to parse multipart stream. Pass the incoming field file stream directly as the \'Body\' of Upload from @aws-sdk/lib-storage. It uses S3 multipart upload under the hood with configurable chunk size.',
                                        ],
                                        [
                                            'text' => 'Explain distributed distributed locking in a Node.js microservices ecosystem. When should you use Redis Redlock versus PostgreSQL advisory locks (pg_advisory_lock)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Redis Redlock: fast, distributed across multiple Redis nodes, handles TTL expiration, good for high-throughput distributed caching. Postgres advisory locks: strictly transactional, automatically freed on connection termination or rollback.',
                                        ],
                                    ],
                                ],
