                                        [
                                            'text' => 'How do you measure and alert on Event Loop delay in a production Node.js service using perf_hooks (monitorEventLoopDelay)? What threshold indicates severe server degradation?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use `perf_hooks.monitorEventLoopDelay({ resolution: 20 })`. Track p50, p95, p99 percentiles. If p99 delay exceeds 50-100ms, event loop is starving from CPU blocking, causing request queuing and HTTP 504 timeouts.',
                                        ],
                                        [
                                            'text' => 'How do you structure an audit logging system in Node.js that records every mutation without adding latency to the client HTTP response or dropping logs on sudden process termination?',
