                                            'note' => 'Record audit payload in AsyncLocalStorage, dispatch to background queue (BullMQ/Redis) or write to stdout via Pino (asynchronous logging) where container log shippers (Fluentbit/Vector) ingest it out-of-band.',
                                        ],
                                        [
                                            'text' => 'How do you implement OpenTelemetry distributed tracing across a Node.js microservices architecture? Explain trace ID propagation across HTTP headers (traceparent) and database queries.',
