                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '1. Add new column (nullable). 2. Deploy Node code writing to both old and new columns, reading from old. 3. Backfill old data to new column. 4. Deploy code reading from new column. 5. Drop old column safely.',
