                                                                        'questions' => [
                                        [
                                            'text' => 'Explain the internal architecture of Node.js C++ Addons (N-API / Node-API) versus WebAssembly (WASM). How do you pass data between JavaScript and native C++ code without expensive serialization overhead?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Node-API provides ABI stability across Node versions. Direct memory sharing is achieved via typed arrays (Uint8Array) and ArrayBuffers (napi_get_arraybuffer_info). Contrast with WASM memory layout and sandboxing.',
                                        ],
                                        [
                                            'text' => 'How does V8 Generational Garbage Collection work under the hood? Explain Scavenge (semi-space nursery with Cheney\'s copy algorithm) versus Mark-Sweep-Compact in Old Space.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'New space (young generation) holds short-lived objects; Scavenger copies surviving objects between From and To spaces. After surviving two cycles, objects are promoted to Old Space. Old Space uses Mark-Sweep (free list) and Mark-Compact to eliminate fragmentation.',
                                        ],
                                        [
                                            'text' => 'How does V8 desugar and execute async/await internally? How has V8 optimized Promise resolution and zero-cost async stack traces across microtask boundaries?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Async/await compiles to generators driven by Promise resolution. V8 avoids wrapping non-promise returns in redundant Promise objects. Zero-cost async stack traces stitch the parent call stack from Promise continuation points.',
                                        ],
                                        [
                                            'text' => 'Explain HTTP/2 multiplexing implementation in Node.js http2 core module. How does binary framing, stream prioritization, and HPACK header compression differ from HTTP/1.1 pipelining?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'HTTP/2 breaks requests into binary frames multiplexed over a single TCP connection, eliminating head-of-line blocking at application layer. HPACK compresses headers via static/dynamic tables. Contrast with HTTP/1.1 keep-alive.',
                                        ],
                                        [
                                            'text' => 'When a production Node.js service experiences an unhandled promise rejection or fatal exception, how do you capture a core dump / diagnostic report and restart cleanly without dropping in-flight traffic?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use process.report.writeReport() or `--report-on-fatalerror`. Trigger graceful shutdown of current worker while health checks failover traffic to sibling workers in the replica set before process exits.',
                                        ],
                                    ],
