                                            'note' => 'Verify HMAC webhook signature. Extract idempotency key. Use Redis `SET key val NX EX 300` or Postgres `INSERT ... ON CONFLICT DO NOTHING` inside a database transaction. Log raw event, return HTTP 200 immediately, and process asynchronously.',
                                        ],
