                                            'note' => 'Aggressive client request timeouts (e.g. 150ms), circuit breakers tripping to fallback/cache, bulkhead isolation (limiting concurrent connections to auth service), and retry budgets with jittered exponential backoff.',
                                        ],
                                        [
                                            'text' => 'How do you implement Probabilistic Early Cache Expiration (XFetch algorithm) in Node.js to completely prevent Cache Stampede (dog-piling) on high-traffic Redis keys?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'XFetch calculates: `-delta * beta * ln(random()) > expiry - now`. If true, background worker recomputes cache before it expires. The closer to expiration and the longer computing takes, the higher probability a single worker regenerates it.',
                                        ],
                                        [
                                            'text' => 'How do you design multi-tenant data isolation in a shared Node.js application? Compare separate schema per tenant, separate database per tenant, and row-level security (RLS) in PostgreSQL.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Separate DB: strongest isolation, high operational overhead. Separate schema: balanced, migration complexity. Shared table with RLS: tenant_id on every row, Postgres policies enforce isolation via `SET LOCAL app.current_tenant_id`.',
                                        ],
