                                            'text' => 'Design a memory-bounded streaming data pipeline in Node.js that exports 20 million database rows into a compressed GZIP CSV download with maximum RAM usage capped at 100MB.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use database cursor stream (pg-query-stream), pipe through Transform stream converting JSON to CSV strings, pipe through zlib.createGzip(), pipe directly to HTTP response stream. Stream backpressure keeps memory under 100MB.',
                                        ],
