                                            'note' => 'Explain that GIL prevents multiple native threads from executing Python bytecodes simultaneously to protect CPython memory management (reference counting). CPU-bound code needs multiprocessing or C extensions; I/O-bound code benefits from threading/asyncio as GIL is released during system calls.',
