                                            'note' => 'Reference counting immediately deallocates memory when refcount drops to zero. Cyclic references (e.g. A->B->A) cannot reach zero, so CPython runs a cyclic garbage collector using a doubly-linked list across 3 generations based on allocation thresholds.',
