                                            'note' => 'Define RLS policy on Postgres tables (`tenant_id = current_setting(\'app.current_tenant_id\')`). In SQLAlchemy session event listener (`before_cursor_execute`), execute `SET LOCAL app.current_tenant_id = :tenant_id` on the transaction.',
                                        ],
