                                            'text' => 'How do you implement OpenTelemetry tracing and metrics instrumentation in FastAPI services? Walk through correlating distributed spans between FastAPI, SQLAlchemy, and external HTTP calls.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use `FastAPIInstrumentor`, `SQLAlchemyInstrumentor`, and `HTTPXClientInstrumentor`. Traces generate Trace ID and Span ID, injecting W3C headers into outbound requests and logging Trace ID in structured logs for unified correlation.',
