                                        [
                                            'text' => 'Explain the Python Virtual Machine (PVM) bytecode evaluation loop (`ceval.c`). How do opcodes get dispatched, and how has Python 3.12+ Specialized Adaptive Interpreter (PEP 659) optimized hot bytecode execution?',
                                            'category' => 'technical',
