                                            'note' => 'PVM is a stack-based machine. PEP 659 introduces specialized bytecodes (e.g. `LOAD_ATTR` specializes to `LOAD_ATTR_INSTANCE_VALUE` or `LOAD_ATTR_SLOT`) that bypass dict lookups when object types remain monomorphic.',
                                        ],
                                        [
                                            'text' => 'Deep dive into Free-Threaded Python (PEP 703 - no-GIL mode in Python 3.13+). What internal changes replace the GIL (biased reference counting, mimalloc), and what are the thread-safety implications for application developers?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'PEP 703 removes GIL using mimalloc thread-safe memory allocator, deferred reference counting for immortal/static objects, and biased reference counting. Thread-safe locks are still required for shared mutable user data structures.',
                                        ],
