                                            'text' => 'How do Cython and C-extension bindings (PyBind11 / CFFI) interface with CPython? Explain memory sharing with NumPy buffers via the Python Buffer Protocol (`Py_buffer`).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Buffer Protocol allows C extensions and Python objects to share raw memory pointers without copying bytes (e.g. NumPy array memory passed directly to C function). Release GIL with `with nogil:` block for high-performance C computations.',
