                                            'text' => 'How do signal handling, OS process signals (SIGTERM, SIGHUP), and graceful shutdown work inside Python\'s asyncio event loop?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Register signal handlers via `loop.add_signal_handler(signal.SIGTERM, callback)`. Cancel all pending tasks (`asyncio.all_tasks()`), wait for them to finish with `asyncio.gather(*tasks, return_exceptions=True)`, close async generators, and stop loop.',
                                        ],
