                                            'text' => 'What are Python slots (`__slots__`)? Explain how `__slots__` eliminates `__dict__` overhead, impacts attribute access speed, and affects inheritance.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`__slots__` reserves a static descriptor array for attributes instead of allocating a dynamic `__dict__` per instance, reducing memory by 40-70% for millions of small objects. Subclasses must also declare `__slots__` to maintain benefits.',
                                        ],
