                                            'note' => 'Pessimistic: `SELECT ... FOR UPDATE` locks rows until transaction commits (prevents concurrent writes, risk of deadlocks). Optimistic: `UPDATE account SET balance = :new, version = version + 1 WHERE id = :id AND version = :cur`; if rowcount is 0, retry transaction.',
