                                            'text' => 'How does Spring Data JPA / Hibernate manage the persistence context and entity states (New, Managed, Detached, Removed)? What is the First-Level Cache versus Second-Level Cache?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Persistence context is the First-Level Cache (session-scoped, ensures identity map and dirty checking). Changes are flushed at transaction commit. Second-Level Cache (Ehcache, Hazelcast) is factory-scoped across sessions for read-heavy entities.',
                                        ],
                                        [
                                            'text' => 'Explain the N+1 problem in Hibernate and JPA. How do you resolve it using `JOIN FETCH` queries, `@EntityGraph`, and batch fetching (`@BatchSize`)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Fetching child collections in Lazy mode executes N queries. `JOIN FETCH` performs SQL inner/left join in JPQL. `@EntityGraph` specifies eager attributes declaratively. `@BatchSize(size = 25)` executes `IN (?, ?, ...)` queries in batches instead of N individual queries.',
                                        ],
                                        [
                                            'text' => 'How does Spring Transaction Management (`@Transactional`) work? Explain transaction propagation types (`REQUIRED`, `REQUIRES_NEW`, `NESTED`) and why self-invocation (`this.method()`) bypasses transaction boundaries.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '@Transactional is implemented via Spring AOP proxies. Self-invocation bypasses the proxy, executing method on target instance without transaction interception. REQUIRED joins existing transaction; REQUIRES_NEW suspends existing and creates a new independent transaction.',
