                                            'note' => 'HikariCP is default in Spring Boot. Rule of thumb for pool size: `(core_count * 2) + effective_spindle_count`. Set connectionTimeout (e.g. 30000ms), maxLifetime (slightly shorter than database idle connection timeout, e.g. 1800000ms), and avoid oversized pools.',
