                                            'text' => 'How do you diagnose and troubleshoot JVM performance issues (High CPU, OutOfMemoryError, Memory Leaks) using thread dumps (`jstack`), heap dumps (`jmap` / `-XX:+HeapDumpOnOutOfMemoryError`), and Eclipse Memory Analyzer (MAT)?',
