                                            'note' => 'Set `server.shutdown=graceful` and `spring.lifecycle.timeout-per-shutdown-phase=30s`. Embedded Tomcat stops accepting new connections, allows in-flight requests to complete within timeout, and shuts down Spring context beans in reverse dependency order.',
