                                            'note' => 'Configure `RedisCacheManager` with `GenericJackson2JsonRedisSerializer`. Prevent penetration: cache empty/null results with short TTL. Prevent breakdown (stampede): use distributed lock (Redisson) or warm caches before key expiry.',
