                                            'text' => 'Deep dive into Virtual Threads in Java 21+ (Project Loom). How do Virtual Threads differ from OS Platform Threads, how does the carrier thread work stealing work, and what is thread pinning (synchronized blocks)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Virtual threads are lightweight user-mode threads managed by JVM (millions can run concurrently). Carrier platform thread mounts virtual thread; unmounts when blocking on I/O. Pinning occurs when virtual thread blocks inside a `synchronized` block or native method, preventing unmounting. Solution: use `ReentrantLock`.',
                                        ],
                                        [
                                            'text' => 'Explain Java Concurrency Primitives: compare `synchronized`, `ReentrantLock`, `StampedLock`, and `AtomicReference`. What is the memory barrier semantics of the `volatile` keyword under the Java Memory Model (JMM)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`volatile` guarantees visibility (flushes CPU cache to main memory) and ordering (prevents compiler/CPU instruction reordering via load/store memory barriers). StampedLock supports optimistic reads. ReentrantLock supports fairness and timeouts.',
                                        ],
                                        [
                                            'text' => 'How does Spring AOP work under the hood? Compare JDK Dynamic Proxies (interface-based) with CGLIB proxies (subclass-based). When does Spring Boot 3 enforce CGLIB by default?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'JDK Dynamic Proxy implements target interfaces via `java.lang.reflect.Proxy`. CGLIB generates bytecode subclasses extending target class. Spring Boot 2.x/3.x enables `spring.aop.proxy-target-class=true` by default (CGLIB) so beans without interfaces can be proxied.',
