                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Parent delegation: classloader asks parent first before loading. Fat JARs contain nested JARs; JVM standard ClassLoader cannot load nested JARs. Spring Boot provides custom `JarLauncher` and `LaunchedURLClassLoader` that unpacks and indexes nested archives.',
