                                        [
                                            'text' => 'Explain the internal mechanics of JVM Just-In-Time (JIT) compilation (C1 Client Compiler, C2 Server Compiler, Tiered Compilation). How does Escape Analysis allow Scalar Replacement and Lock Elision?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Tiered compilation: bytecode is interpreted, compiled by C1 (fast compilation with profiling), hot methods recompiled by C2 (heavy optimization). Escape Analysis determines if object escapes thread/method: if not, JVM allocates on stack or replaces with scalar primitives (scalar replacement), and removes redundant locks (lock elision).',
                                        ],
                                        [
                                            'text' => 'How does Java memory layout and object alignment work on 64-bit JVMs? Explain Compressed OOPs (`-XX:+UseCompressedOops`), Object Headers (Mark Word, Klass Word), and False Sharing (CPU cache line padding with `@Contended`).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Objects aligned to 8-byte boundaries. Object header = 8-byte Mark Word + 4/8-byte Klass Word. Compressed OOPs represent 64-bit pointers in 32 bits for heaps <32GB. False Sharing occurs when variables on same 64-byte CPU cache line are modified by different threads; `@Contended` pads cache line.',
                                        ],
                                        [
                                            'text' => 'Compare Native Compilation with GraalVM Native Image versus standard JVM execution in Spring Boot 3. What are the trade-offs regarding startup time, peak throughput, reflection configuration, and memory footprint?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'GraalVM Ahead-Of-Time (AOT) compiles Java to native binary: instant startup (<50ms) and low memory (30MB), perfect for serverless/K8s scale-from-zero. Trade-offs: longer build times, closed-world assumption (requires reflection/proxy metadata hints), lower peak throughput than C2 JIT profile-guided optimization.',
                                        ],
                                        [
                                            'text' => 'How do Lock-Free data structures work in Java (`ConcurrentLinkedQueue`, `LongAdder`)? Explain Compare-And-Swap (CAS) instructions (`sun.misc.Unsafe` / `VarHandle`), the ABA problem, and how `AtomicStampedReference` solves it.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Lock-free structures use hardware atomic CAS (`lock cmpxchg`). `LongAdder` reduces cache contention under high concurrency by maintaining array of cells. The ABA problem occurs when value changes from A to B and back to A; `AtomicStampedReference` associates an integer stamp/version with reference.',
                                        ],
                                        [
                                            'text' => 'Explain JVM Thread Dumps and thread state transitions (NEW, RUNNABLE, BLOCKED, WAITING, TIMED_WAITING). How do you identify Java deadlocks and monitor lock contention programmatically via `ThreadMXBean`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'BLOCKED indicates thread waiting to enter synchronized monitor; WAITING indicates waiting for notify/join or ReentrantLock condition. `ThreadMXBean.findDeadlockedThreads()` inspects object monitor and ownable synchronizer cycles, returning thread IDs involved in deadlock.',
                                        ],
                                    ],
                                ],
