                                                                        'questions' => [
                                        [
                                            'text' => 'Architect a distributed transaction coordination system across independent relational and NoSQL databases in Java without using two-phase commit (2PC) / XA transactions.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'XA/2PC creates blocking locks across nodes, destroying availability and scalability. Use Transactional Outbox pattern with Change Data Capture and Idempotent Consumers, or an asynchronous Orchestrated Saga with compensating workflows.',
                                        ],
                                        [
                                            'text' => 'How do you detect and prevent database deadlocks and lock escalation in high-throughput Spring Boot enterprise applications processing 50,000 transactions/minute?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Enforce strict global lock ordering across all queries. Keep database transactions short (move third-party API calls outside `@Transactional`). Use short lock timeouts (`SET lock_timeout = 3000`). Retry deadlocked transactions using `@Retryable(retryFor = CannotAcquireLockException.class)`.',
                                        ],
                                        [
                                            'text' => 'Design a multi-region active-active deployment architecture for a Spring Boot payment engine with zero data loss (RPO=0) and sub-second recovery (RTO<1s).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use globally distributed multi-master database (Google Spanner / CockroachDB / AWS Aurora Global DB with write forwarding). Route users by region. Use conflict-free replicated data types (CRDTs) or distributed consensus (Raft). Replicate idempotency keys across regions.',
                                        ],
                                        [
                                            'text' => 'How do you build a resilient, high-throughput reactive event streaming architecture using Spring Cloud Stream, Kafka Streams, and RocksDB state stores?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Kafka Streams maintains stateful aggregations (windowing, joins) in local RocksDB embedded instances. Periodically writes changelog topics to Kafka for fault tolerance. Spring Cloud Stream binds functions (`java.util.function.Consumer / Function`) to broker topics declaratively.',
                                        ],
                                        [
                                            'text' => 'How do you audit and profile production latency bottlenecks in Java services using Continuous Profiling (e.g. Pyroscope, Grafana Phono, Datadog Profiler)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Continuous profiler uses async-profiler (signals like SIGPROF) with minimal overhead (<1% CPU). Generates flame graphs of CPU on-path execution, off-CPU waiting (lock contention, socket I/O), and memory allocations, pinpointing exact method hotspots.',
                                        ],
                                    ],
