                                        [
                                            'text' => 'Conduct a production post-mortem: A mission-critical Java microservice suffered severe stop-the-world GC pauses (>10 seconds) leading to cluster eviction. GC logs showed concurrent mode failures and allocation spikes. How do you analyze GC logs, tune heap parameters, and resolve this?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Analyze GC logs with GCEasy. Concurrent mode failure occurs in G1/CMS when Old Gen fills faster than concurrent marking finishes. Mitigation: increase heap (`-Xmx`), initiate marking earlier (`-XX:InitiatingHeapOccupancyPercent=40`), increase marking threads (`-XX:ConcGCThreads`), or transition to ZGC.',
                                        ],
                                        [
                                            'text' => 'How do you architect a mission-critical double-entry accounting ledger engine in Java ensuring ACID transactions, auditability, and mathematical immutability?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Every transaction has balanced debits and credits (`sum(debits) - sum(credits) == 0`). Entries are strictly append-only (no UPDATE/DELETE). Enforce database constraints and cryptographic hash chains (SHA-256 linking each entry to previous entry). Lock account balances via optimistic versioning.',
                                        ],
                                        [
                                            'text' => 'How do you conduct Chaos Engineering on a Spring Boot microservice cluster? Walk through injecting thread pool starvation, latency, and database network partitions using Chaos Toolkit or Chaos Mesh.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Inject network delay on database port 5432 to verify HikariCP connectionTimeout trips and returns HTTP 503 instead of hanging threads. Simulate network partition to verify Eureka/Kubernetes service discovery health checks and circuit breaker fallbacks.',
                                        ],
                                        [
                                            'text' => 'Design a zero-trust enterprise security architecture for Java microservices incorporating mTLS, SPIFFE/SPIRE identity attestation, and dynamic role-based authorization.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'SPIFFE provides cryptographic workload identity via X.509 SVIDs rotated automatically. Service mesh handles mTLS. Java microservice decodes SPIFFE ID from client certificate, mapping to Spring Security PreAuthorize expressions.',
                                        ],
                                        [
                                            'text' => 'How do you design a high-frequency trading or ultra-low-latency order processing pipeline in Java with sub-millisecond p99 latency using LMAX Disruptor ring buffer?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Disruptor uses a pre-allocated circular ring buffer with power-of-two size, lock-free sequence barriers, and CPU cache-line padding (eliminating false sharing). Avoids Garbage Collection entirely by reusing pre-allocated event objects.',
                                        ],
                                    ],
