                                            'text' => 'Explain the Go Concurrency Model (GMP Scheduler). What are G (Goroutine), M (OS Machine Thread), and P (Processor Context)? How does work stealing and sysmon runtime thread management work?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'G = Goroutine (stack starts at 2KB). M = OS Thread. P = Logical Processor (GOMAXPROCS). P holds local run queue. When P\'s local queue is empty, it steals half of another P\'s queue. sysmon is background thread handling preemption (signals) and network poller.',
                                        ],
                                        [
                                            'text' => 'Compare Buffered versus Unbuffered Channels in Go. What causes Goroutine deadlocks, and what happens when sending to or receiving from a closed channel?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Unbuffered channel: send blocks until receiver is ready (synchronous rendezvous). Buffered channel: send blocks only when buffer is full. Sending to a closed channel panics; receiving from closed channel yields zero value and `ok == false`. Sending/receiving from nil channel blocks forever.',
                                        ],
                                        [
                                            'text' => 'Explain Go memory allocation: Stack versus Heap. What is Escape Analysis (`go build -gcflags=\'-m\'`), and what code patterns cause variables to escape to the heap?',
