                                            'note' => 'Compiler determines if variable lifecycle extends beyond function scope. Escapes to heap: returning pointers to local variables, passing pointers to interface{} methods (e.g. `fmt.Println`), slice capacity exceeding stack limits, or slices with dynamic sizes.',
