                                            'text' => 'How do Interfaces work in Go under the hood? Explain the `iface` (interface with methods) and `eface` (empty interface) runtime structures (`_type` and `data` pointer). Why is `var err error = (*MyError)(nil)` not equal to `nil`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'An interface is a two-word pair: type pointer and data pointer. An interface is `nil` ONLY when both type and data are nil. When a typed nil pointer is assigned to an interface, the interface\'s type is non-nil (`*MyError`), so `err != nil` evaluates to true!',
                                        ],
