                                            'text' => 'Conduct a production post-mortem: A high-throughput Go API service experienced sudden latency degradation where p99 rose from 5ms to 800ms. CPU profiler showed massive time in `runtime.findrunnable` and `runtime.futex`. How do you diagnose and fix this scheduler lock contention?',
