                                    'tags' => [
                                        'react_nextjs',
                                        'frontend',
                                        'series_1',
                                        'set_1',
                                        'foundations',
                                    ],
                                                                        'questions' => [
                                        [
                                            'text' => 'Explain the difference between React Server Components (RSC) and Client Components (\'use client\') in Next.js App Router. How do component boundaries, bundle sizes, and hydration work across this divide?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Server components render on server only, zero JavaScript sent to client, direct backend/DB access. Client components (\'use client\') hydrate on client for interactivity (useState, useEffect, browser events). Passing Server Component as children to Client Component keeps it on server.',
                                        ],
                                        [
                                            'text' => 'How does React Fiber reconciliation architecture work? Explain Fiber nodes, the work-in-progress tree, and how Concurrent React prioritizes high-priority updates (user input) over low-priority updates (data fetching).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Fiber is a linked-list representation of virtual DOM allowing interruptible, cooperative rendering. Two trees: current and workInProgress. High-priority updates (clicks, typing) preempt low-priority updates (transitions, off-screen rendering) via scheduler lanes.',
                                        ],
                                        [
                                            'text' => 'Explain the rules of React Hooks. Why must hooks never be called conditionally or inside loops? How does React internally track hook state across re-renders using Fiber linked lists?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'React stores hook states in a singly linked list attached to the component\'s Fiber node (`memoizedState`). On re-render, React traverses this list in exact call order. Conditional calls break pointer index alignment, corrupting state.',
                                        ],
                                        [
                                            'text' => 'What are Hydration Errors in Next.js? What causes hydration mismatches (e.g. `typeof window`, dates, random IDs), and how do you resolve them cleanly using `useEffect` or dynamic imports with `{ ssr: false }`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Hydration mismatch occurs when server-rendered HTML does not match client initial render tree. Resolve by moving client-only logic into `useEffect` (runs after hydration), using `suppressHydrationWarning`, or `next/dynamic` with `{ ssr: false }`.',
                                        ],
                                        [
                                            'text' => 'Compare `useCallback`, `useMemo`, and `React.memo`. When does over-optimizing with `useCallback` and `useMemo` actually hurt performance due to dependency comparison overhead?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`React.memo` skips re-rendering if props are shallow equal. `useCallback` memoizes function instance; `useMemo` memoizes computed value. Overusing adds memory overhead and array comparison CPU on every render without real child re-render savings.',
                                        ],
                                    ],
