                                        [
                                            'text' => 'Explain the Next.js App Router Caching layers: Request Memoization, Data Cache (`fetch` cache), Full Route Cache (HTML & RSC payload on server), and Router Cache (in-memory on client). How do `revalidatePath` and `revalidateTag` work?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Request Memoization deduplicates identical GET requests in same render pass. Data Cache persists data across requests/deployments. Full Route Cache caches static routes. Router Cache stores prefetched routes in browser. `revalidateTag(\'tag\')` purges Data Cache on demand.',
                                        ],
                                        [
                                            'text' => 'How does React Suspense and Streaming Server-Side Rendering (SSR) work in Next.js? How does `loading.tsx` enable progressive UI streaming over chunked HTTP transfer encoding?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Next.js streams initial shell HTML immediately. Slow data-fetching components wrapped in Suspense render fallback (`loading.tsx`). When data resolves on server, HTML and inline script stream in chunks, replacing fallback in-place without page reload.',
                                        ],
                                        [
                                            'text' => 'Compare modern state management approaches in React: Context API, Zustand, and Redux Toolkit. When does Context API cause unnecessary component re-renders and how do atomic/selector state libraries solve it?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Context re-renders all consumers whenever value changes, even if component only consumes a slice of the value. Zustand uses external store with selector subscriptions (`useStore(state => state.foo)`), re-rendering only when selected slice changes.',
                                        ],
                                        [
                                            'text' => 'How do React Server Actions work in Next.js? How do you handle form submissions, pending states (`useActionState` / `useFormStatus`), optimistic UI updates (`useOptimistic`), and server validation with Zod?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Server Actions are asynchronous server functions invoked from client forms (via POST request). `useActionState` manages form state/errors. `useOptimistic` updates UI immediately while action is executing on server, reverting if action fails.',
                                        ],
                                        [
                                            'text' => 'How do you optimize Web Vitals in Next.js: Largest Contentful Paint (LCP), Interaction to Next Paint (INP), and Cumulative Layout Shift (CLS) using `next/image`, `next/font`, and dynamic script loading?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`next/image` handles responsive sizing, WebP conversion, and prevents CLS with explicit width/height. `next/font` inlines font definitions at build time (zero font layout shift). LCP optimized with `priority` attribute on hero images.',
                                        ],
