                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Virtualization renders only the visible window of items (e.g. 10-15 DOM nodes) plus a small overscan buffer. Tracks scroll position, calculates absolute transform Y offsets, drastically reducing DOM nodes and memory.',
