                                                                        'questions' => [
                                        [
                                            'text' => 'Compare `type` aliases and `interface` in TypeScript. How do they handle declaration merging, extending/intersections, and union types?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Interfaces support declaration merging (multiple declarations with same name merge properties). Types cannot merge. Types support unions, primitives, and tuples directly. Interfaces are preferred for public library APIs and object shapes.',
                                        ],
                                        [
                                            'text' => 'Explain TypeScript Generics and Generic Constraints (`<T extends Record<string, any>>`). How do you enforce that a generic argument contains specific properties without losing narrow return types?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Generics provide reusable type logic. Constraints with `extends` restrict allowed types. Using `K extends keyof T` preserves key types when indexing `T[K]`. Preserves exact literal return type rather than widening to base constraint.',
                                        ],
                                        [
                                            'text' => 'Compare `unknown`, `any`, and `never` in TypeScript. What are the sound type-narrowing practices for `unknown` using type guards and Zod?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`any` disables all type-checking (escape hatch). `unknown` is type-safe top type (requires narrowing before property access). `never` is bottom type (represents values that never occur, e.g. exhaustive checks). Use custom type guards (`val is string`) or Zod schema parsing.',
                                        ],
                                        [
                                            'text' => 'How do User-Defined Type Guards (`arg is Type`) and Assertion Functions (`asserts condition`) work? How do they narrow types inside conditional branches?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Type guard returns boolean with type predicate `arg is SpecificType`. Inside `if (isType(x))`, compiler narrows `x` to `SpecificType`. Assertion functions (`asserts val is SpecificType`) throw if invalid, narrowing type for all subsequent code.',
                                        ],
                                        [
                                            'text' => 'Explain discriminated unions (tagged unions) in TypeScript. How do you implement exhaustive checking using the `never` type in `switch` statements to catch missing enum cases at compile-time?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Each type in union shares a literal discriminator property (e.g. `type: \'success\' | \'error\'`). In `switch`, handle all cases. In `default`, assign value to variable of type `never` (`const _exhaustive: never = value`). If a case is missed, compiler throws error.',
                                        ],
                                    ],
                                ],
                                [
                                    'id' => 'frontend-typescript-s1-set2',
                                    'series_number' => 1,
                                    'set_number' => 2,
                                    'title' => 'Set 2: Problem Solving & Scalable Implementation',
                                    'duration_minutes' => 15,
                                    'description' => 'Implementation depth: data structures, query tuning, asynchronous pipelines, and caching patterns.',
                                    'tags' => [
                                        'typescript',
                                        'frontend',
                                        'series_1',
                                        'set_2',
                                        'implementation',
                                    ],
                                                                        'questions' => [
                                        [
                                            'text' => 'Explain TypeScript Utility Types: `Pick`, `Omit`, `Partial`, `Required`, `Readonly`, and `Record`. How are they implemented internally using mapped types and `keyof`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Mapped types iterate over keys: `[P in K]: T[P]`. `Partial<T>` adds `?` modifier: `[P in keyof T]?: T[P]`. `Omit<T, K>` combines `Pick<T, Exclude<keyof T, K>>`. `Record<K, T>` maps keys `K` to value `T`.',
                                        ],
                                        [
                                            'text' => 'How do Conditional Types (`T extends U ? X : Y`) work in TypeScript? Explain distributive conditional types across naked type parameters in unions.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Conditional types evaluate condition based on subtyping. When applied to a naked generic type parameter `T`, unions distribute over the condition: `(A | B) extends U ? X : Y` becomes `(A extends U ? X : Y) | (B extends U ? X : Y)`. Prevent distribution by wrapping in tuple `[T]`.',
                                        ],
                                        [
                                            'text' => 'What is the `infer` keyword in TypeScript? How do you extract return types from functions (`ReturnType<T>`) or element types from Promise/arrays using `infer`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`infer` introduces a type variable within the `extends` clause of a conditional type. Example: `type ReturnType<T> = T extends (...args: any[]) => infer R ? R : any`. For Promises: `type Awaited<T> = T extends Promise<infer U> ? U : T`.',
                                        ],
                                        [
                                            'text' => 'Explain Template Literal Types in TypeScript (e.g. `type Event = \\`on\\${Capitalize<string>}\\``). How do they enable strongly typed event emitters and CSS utility class validation?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Template literal types construct types by combining string literal types with string formatting utilities (`Uppercase`, `Lowercase`, `Capitalize`, `Uncapitalize`). Enables type-safe event handlers (`onUserClick`), URL routes (`/users/${string}`), and CSS units (`${number}px`).',
                                        ],
                                        [
                                            'text' => 'How does TypeScript configuration (`tsconfig.json`) impact strictness? Explain the implications of `strictNullChecks`, `noImplicitAny`, `exactOptionalPropertyTypes`, and `noUncheckedIndexedAccess`.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`strictNullChecks` prevents assigning null/undefined to other types. `exactOptionalPropertyTypes` distinguishes `{ a?: string }` from `{ a?: string | undefined }`. `noUncheckedIndexedAccess` adds `undefined` to dictionary lookup results (`T[string]` becomes `T | undefined`), preventing runtime crashes.',
                                        ],
                                    ],
                                ],
