                                            'text' => 'Explain Nominal Typing vs Structural Typing in TypeScript. How do you implement Branded Types (or Flavored Types) to prevent accidentally mixing up IDs (e.g. `UserId` vs `OrderId`)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'TypeScript is structurally typed (identical shapes are interchangeable). Branded types simulate nominal typing using a phantom unique brand property: `type UserId = string & { readonly __brand: unique symbol }`. Requires explicit constructor/validator function to create.',
                                        ],
                                        [
                                            'text' => 'How do Function Overloads work in TypeScript? Contrast overload signatures with implementation signature, and explain when union types are preferred over overloads.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Define one or more overload signatures followed by a single compatible implementation signature. Callers only see overload signatures; implementation signature is hidden. If return type depends simply on parameter type, conditional types or unions are often cleaner.',
                                        ],
                                        [
                                            'text' => 'How do you build a type-safe API client with runtime validation using Zod and TypeScript (`z.infer<typeof Schema>`)? Why is runtime validation essential alongside compile-time types?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'TypeScript types disappear at runtime. External API data can deviate from types. Zod parses and validates data at runtime; `z.infer<typeof MySchema>` generates the TypeScript type automatically, guaranteeing synchronization between runtime validation and compile-time types.',
                                        ],
                                        [
                                            'text' => 'What are TypeScript Const Assertions (`as const`) and `satisfies` operator (TS 4.9+)? How does `satisfies` preserve narrow types while still validating against an interface?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`as const` makes all properties `readonly` and literal values. Type annotation `const x: Type = ...` widens properties to base type. `satisfies` validates that expression matches type `Type` without widening property types, preserving autocomplete and narrow inferences.',
                                        ],
                                        [
                                            'text' => 'How do you declare ambient types and module augmentations (`declare module \'package\'`) in TypeScript to extend third-party library types (e.g. adding custom properties to Express `Request` or NextAuth `Session`)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use `declare module \'express\'` with interface merging: `namespace Express { interface Request { user?: User; } }`. File must import the target module or be included in tsconfig `include`. Module augmentation merges custom properties directly into library types.',
                                        ],
