                                        [
                                            'text' => 'Deep dive into Covariance, Contravariance, Invariance, and Bivariance in TypeScript. Why are method parameters bivariant by default in interfaces, and how does `strictFunctionTypes` enforce contravariance on function properties?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Covariance: Subtype preserved in container (outputs/returns). Contravariance: Subtype reversed (inputs/arguments). `strictFunctionTypes` enforces contravariance on function properties `(x: T) => void`, but leaves method declarations `foo(x: T): void` bivariant for historical array compatibility.',
                                        ],
                                        [
                                            'text' => 'Explain Advanced Recursive Types in TypeScript (e.g. `DeepReadonly<T>`, `DeepPartial<T>`, and flattening nested object keys into dot-notation paths `Paths<T>`). How do you prevent infinite recursion compiler limits?',
                                            'category' => 'technical',
