                                            'note' => 'Recursive type checks if `T[K] extends object ? DeepReadonly<T[K]> : T[K]`. For dot-notation paths, recurse on object keys with template literals `${K}.${Paths<T[K]>}`. Prevent recursion depth error by adding a depth counter tuple `[any, ...Depth]` with max limit (e.g. 5 levels).',
                                        ],
