                                                                        'questions' => [
                                        [
                                            'text' => 'Explain the end-to-end architecture of a MERN (MongoDB, Express, React, Node.js) application. How do requests flow from a React client through Express middleware, Mongoose ODM, to MongoDB, and back?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Client React makes fetch/axios request. Express router receives request, passes through middleware (CORS, body-parser, auth). Controller calls Mongoose schema methods, executing BSON query over MongoDB driver connection pool. Response returns as JSON to React state.',
                                        ],
                                        [
                                            'text' => 'How do MongoDB Indexing strategies work (Single field, Compound, Multikey, Text)? What is an index scan (IXSCAN) versus collection scan (COLLSCAN) in MongoDB `explain(\'executionStats\')`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Indexes are B-trees. Compound indexes follow Equality, Sort, Range (ESR) rule. COLLSCAN scans every document in collection (slow, high CPU); IXSCAN uses index to locate matching pointers. Covered queries satisfy query and projection entirely from index.',
                                        ],
                                        [
                                            'text' => 'How does Mongoose handle Schema validation, middleware hooks (`pre(\'save\')`, `post(\'save\')`), and virtual fields? What is the difference between document middleware and query middleware?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Schema validates types, required, custom validators. Document middleware (`pre(\'save\')`) has `this` bound to document (ideal for password hashing with bcrypt). Query middleware (`pre(\'find\')`) has `this` bound to query. Virtuals are computed properties not stored in MongoDB.',
                                        ],
                                        [
                                            'text' => 'Explain JWT (JSON Web Token) authentication architecture in MERN. Where should tokens be stored on the client (HttpOnly Cookies vs localStorage) to mitigate XSS and CSRF attacks?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'localStorage is vulnerable to XSS (any injected script can steal token). HttpOnly cookies cannot be accessed by JavaScript (XSS-proof). To prevent CSRF with cookies, set `SameSite=Strict` (or `Lax`) and implement CSRF tokens for mutating requests.',
                                        ],
                                        [
                                            'text' => 'How do you structure API error handling in Express to ensure all asynchronous errors (rejected Promises) are captured without crashing the Node.js server?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Express 4 requires wrapping async handlers in `try/catch` and calling `next(err)` or using `express-async-errors`. Express 5 natively catches rejected promises from async handlers. Centralized error middleware with signature `(err, req, res, next)` formats JSON error.',
                                        ],
