                                        [
                                            'text' => 'How does the MongoDB Aggregation Pipeline work? Explain key stages: `$match`, `$group`, `$lookup` (joins), `$project`, and `$unwind`. When should you use aggregation over Mongoose `populate()`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Aggregation pipeline processes documents through ordered stages inside MongoDB engine. `$lookup` performs left outer joins on database server. Mongoose `populate()` executes separate application-level queries; aggregation is drastically faster for large datasets.',
                                        ],
                                        [
                                            'text' => 'How do you implement Refresh Token Rotation with automatic reuse detection in a MERN stack to protect compromised credentials?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Issue short-lived access token (15m) and single-use refresh token (7d) stored in DB family. When refresh token is exchanged, invalidate it and issue new one. If an invalidated refresh token is reused (indicating token theft), revoke entire token family and force re-login.',
                                        ],
                                        [
                                            'text' => 'How do you handle file uploads in MERN using Multer and AWS S3? How do you stream files directly to cloud storage without saving to local server disk?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use `multer-s3` or configure Multer with `memoryStorage()`. Pass file buffer or stream directly to AWS S3 SDK (`PutObjectCommand` / `@aws-sdk/lib-storage`). Validate MIME types and file size limits in Multer fileFilter to prevent malicious file uploads.',
                                        ],
                                        [
                                            'text' => 'How do you optimize React client performance in MERN apps using code-splitting (`React.lazy`), dynamic routing, and bundle visualization?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use `React.lazy()` with `Suspense` for route-based code splitting so users only download JavaScript for active page. Use Vite or Webpack bundle analyzer to spot bloated vendor dependencies. Tree-shake unused lodash/date libraries.',
                                        ],
                                        [
                                            'text' => 'Explain database transactions in MongoDB using Mongoose with replica sets (`session.startTransaction()`). How do you handle rollback on multi-document operations?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'MongoDB transactions require a replica set. Acquire session: `const session = await mongoose.startSession(); session.startTransaction();`. Pass `{ session }` to all Mongoose operations. Call `await session.commitTransaction()` or `await session.abortTransaction()` on error.',
                                        ],
