                                            'text' => 'How do you protect a MERN stack application against NoSQL Injection attacks in Express route inputs (e.g. `req.body.password = { $ne: null }`)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'NoSQL injection occurs when attackers pass MongoDB operator objects (`$gt`, `$ne`) instead of strings, bypassing password checks. Mitigate using `express-mongo-sanitize` (strips `$` and `.`), and validate inputs with Zod/Joi schemas.',
                                        ],
                                        [
                                            'text' => 'How do you implement pagination in MERN: Offset-based (`skip` & `limit`) versus Cursor-based (Keyset pagination)? Why does `skip(100000)` degrade MongoDB performance?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`skip(N)` still scans N index entries before returning results, becoming O(N) and slow. Cursor-based pagination uses indexed unique field: `find({ _id: { $lt: lastSeenId } }).sort({ _id: -1 }).limit(20)`, running in O(1) time regardless of dataset size.',
