                                            'note' => 'Primary accepts writes, replicates to secondaries via oplog. Write concern `w: \'majority\'` returns only after majority of nodes acknowledge write. Read concern `\'majority\'` returns data committed by majority, preventing dirty reads during rollbacks.',
                                        ],
                                        [
                                            'text' => 'How do you architect data schema modeling in MongoDB: Embedding (denormalization) versus Referencing (normalization)? What are the trade-offs regarding 16MB document size limit and atomic updates?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Embedding: ideal for 1-to-few, fast single-query reads, atomic updates on document. Referencing: ideal for 1-to-many / many-to-many, prevents reaching 16MB BSON limit, avoids data duplication. Use Subset Pattern for large historical lists.',
                                        ],
                                        [
                                            'text' => 'How do you implement caching in a MERN application using Redis with Cache-Aside pattern? How do you handle cache invalidation on Mongoose document updates and deletes?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Check Redis for key; if hit, return JSON. On miss, query MongoDB, serialize to Redis with TTL. On mutation in Express controller or Mongoose `post(\'save\')` / `post(\'remove\')` middleware, delete or update corresponding Redis keys.',
