                                            'note' => 'Set headers: `Content-Type: text/event-stream`, `Cache-Control: no-cache`, `Connection: keep-alive`. Stream data format: `data: JSON.stringify(...)

`. React consumes using native browser `EventSource` API with auto-reconnection.',
                                        ],
