                                            'text' => 'Deep dive into MongoDB Sharding Architecture (Mongos Query Router, Config Server Replica Set, Shard Replica Sets). How does chunk splitting, shard balancing, and picking the right Shard Key prevent hot spotting?',
                                            'category' => 'technical',
