                                            'duration_seconds' => 180,
                                            'note' => 'Causal consistency guarantees operations that are causally related are seen by every node in the same order (Read Your Own Writes). Read concern `\'linearizable\'` confirms with majority before returning, preventing stale reads if primary was partitioned.',
