                                                                        'questions' => [
                                        [
                                            'text' => 'Explain the unified fullstack architecture of Next.js App Router. How do Server Components, Route Handlers (`app/api/.../route.ts`), and Server Actions work together to replace traditional separate backend Express servers?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Server components query DB/ORM directly on server. Server Actions handle mutations with automatic cache revalidation. Route Handlers provide standard REST/webhook endpoints returning `NextResponse.json()`. All run in the same Node.js or Edge runtime environment.',
                                        ],
                                        [
                                            'text' => 'How does Data Fetching work in Next.js Fullstack? Compare Server-side direct ORM calls (Prisma/Drizzle inside RSC) versus Route Handlers and client-side fetching with TanStack Query.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Direct DB/ORM calls inside RSC eliminate extra HTTP round-trip latency and serialize zero JS to client. Route Handlers are used for third-party webhooks and mobile apps. Client fetching is reserved for real-time polling or frequently updated interactive state.',
                                        ],
                                        [
                                            'text' => 'Explain Next.js Route Segments, Parallel Routes (`@slot`), and Intercepting Routes (`(..)photo`). How do they enable complex modal views and contextual feeds (like Instagram photo modals)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Parallel routes render independent pages in the same layout simultaneously. Intercepting routes intercept navigation to display a route inside a modal within current context, while direct URL access renders full independent page.',
                                        ],
