                                            'text' => 'Explain Next.js rendering strategies: Static Site Generation (SSG), Server-Side Rendering (SSR), and Incremental Static Regeneration (ISR). How do `generateStaticParams` and `export const revalidate = 60` work?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'SSG builds HTML at build time. SSR generates HTML per request (`dynamic = \'force-dynamic\'`). ISR builds static pages and regenerates them in background every N seconds or on-demand (`revalidateTag`). `generateStaticParams` generates dynamic route parameters at build.',
