                                            'duration_seconds' => 180,
                                            'note' => 'In development, HMR instantiates new PrismaClient on every file save, exhausting DB connections. Prevent by attaching Prisma instance to `globalThis.prisma`. Drizzle operates with lightweight SQL drivers (e.g. pg / serverless drivers) compatible with Edge runtime.',
