                                            'note' => '`revalidatePath(\'/posts\')` purges all caches associated with specific URL path. `revalidateTag(\'posts\')` purges any cached fetch call across the entire app that included `{ next: { tags: [\'posts\'] } }`, regardless of which page requested it.',
