                                            'text' => 'How do you optimize memory and CPU performance in Next.js Fullstack applications deployed in containerized environments (Kubernetes) to prevent OOM kills during build and runtime?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Set `NODE_OPTIONS=\'--max-old-space-size=2048\'`. Disable source maps in production (`productionBrowserSourceMaps: false`). Tune sharp memory pool for image optimization. Use `experimental.cpus` to limit build worker concurrency.',
                                        ],
                                        [
                                            'text' => 'How do you architect an audit logging and compliance tracking system in Next.js Fullstack that records every user mutation executed via Server Actions or Route Handlers?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Wrap Server Actions with a higher-order action creator (`createAuditedAction`). Automatically extracts authenticated user ID, IP address, user-agent, action name, and parameters, writing immutable audit record to database inside transaction.',
                                        ],
                                        [
                                            'text' => 'How do you implement rate limiting and bot detection in Next.js using Upstash Redis with Sliding Window algorithms and Cloudflare Turnstile in Server Actions?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Validate Turnstile token in Server Action via Cloudflare API. Check rate limit using `@upstash/ratelimit` on Redis. If limit exceeded or captcha invalid, return error before executing sensitive database logic.',
                                        ],
                                        [
                                            'text' => 'How do you implement full-text search in Next.js Fullstack using PostgreSQL pgvector / full-text search (tsvector) with GIN indexing versus external search engines (Algolia/Meilisearch)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'PostgreSQL `to_tsvector` with GIN index provides fast lexical search without external infrastructure. For semantic search, store embeddings with `pgvector` and query using cosine distance (`<=>`). Use Meilisearch for high-scale typo-tolerant multi-attribute filtering.',
                                        ],
                                        [
                                            'text' => 'How do you build a zero-downtime blue-green or canary deployment pipeline for Next.js Fullstack in Kubernetes with asset versioning and sticky routing?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Kubernetes Ingress routes 90% traffic to Blue, 10% to Green. Ensure static assets from both versions are hosted in unified S3/CDN bucket so clients running old JavaScript bundles can fetch their chunk files without 404 errors.',
                                        ],
                                    ],
                                ],
