                                        [
                                            'text' => 'Deep dive into Next.js Compiler internals (SWC / Rust pipeline): How does SWC perform JSX transformation, modularize imports, styled-jsx injection, and server/client bundle splitting?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'SWC parses JavaScript/TypeScript into Rust AST. ModularizeImports transforms top-level barrel imports (`import { Button } from \'ui\'`) into direct subpath imports. Rust compiler splits code into separate client components and server component graph.',
                                        ],
                                        [
                                            'text' => 'Explain the exact wire protocol of Next.js Server Action invocation. How does the browser serialize arguments (FormData / JSON), how does the server stream the response, and how does the client router merge updated RSC trees?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Client makes POST with `Next-Action` header. Server executes action, generates fresh RSC flight payload for revalidated paths, and returns composite response. Client router reconciles flight payload into existing DOM, preserving active form inputs and scroll position.',
                                        ],
                                        [
                                            'text' => 'How does V8 isolate memory and execution in Next.js Edge Runtime compared to standard Node.js event loop? What are the limitations regarding dynamic code evaluation (`eval`), WebAssembly, and native addons?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Edge Runtime runs on lightweight V8 isolates (no Node.js OS bindings, no access to native C++ addons). Disallows dynamic code evaluation for security. Startup latency is sub-millisecond, and hundreds of isolates share OS thread via cooperative scheduling.',
                                        ],
