                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Streaming SSR writes chunks to HTTP response socket immediately, freeing component virtual DOM subtrees from memory as they finish rendering. Avoids buffering entire HTML page in RAM, keeping memory bounded even with 1,000 concurrent streaming requests.',
