                                        [
                                            'text' => 'Explain the core architecture of Retrieval-Augmented Generation (RAG). How do Vector Embeddings, Chunking strategies (fixed-size vs sentence-aware vs semantic), and Cosine Similarity work?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'RAG converts documents into dense vector embeddings. Chunking splits text (chunk_size, chunk_overlap) to preserve context. Query is embedded and compared against chunk embeddings using Cosine Similarity or Dot Product to retrieve top-k relevant context for LLM prompt.',
                                        ],
                                        [
                                            'text' => 'Compare Vector Indexing algorithms: HNSW (Hierarchical Navigable Small World), IVF (Inverted File Index), and Flat indexing. What are the trade-offs between search latency, recall accuracy, and memory usage in Pinecone, Qdrant, or Milvus?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Flat: exact brute-force search (100% recall, high latency O(N)). IVF: clusters vectors into Voronoi cells, searches nearest centroids (fast, requires training). HNSW: multi-layer proximity graphs (ultra-fast O(log N), high recall >98%, higher RAM usage).',
                                        ],
                                        [
                                            'text' => 'How do Context Windows, Tokenization (BPE - Byte Pair Encoding), and Context Stuffing limits impact LLM responses? What is the \'Lost in the Middle\' phenomenon in long-context models?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'BPE breaks text into subword tokens. \'Lost in the Middle\' refers to empirical evidence that LLMs recall information placed at the very beginning or end of long context windows with high accuracy, but struggle to retrieve relevant details placed in the middle.',
                                        ],
                                        [
                                            'text' => 'Explain Prompt Engineering techniques: Zero-shot, Few-shot (in-context learning), Chain-of-Thought (CoT), and ReAct (Reasoning and Acting). How do they improve factual accuracy and reasoning in LLMs?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Zero-shot gives direct prompt. Few-shot provides 2-5 input-output examples guiding format. Chain-of-Thought prompts model to \'think step by step\', breaking complex logic down. ReAct interleaves reasoning traces and external tool executions.',
                                        ],
                                        [
                                            'text' => 'What are Hallucinations in LLMs? Explain why hallucinations occur (probabilistic token generation) and how RAG, temperature tuning, and system prompt grounding mitigate them.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'LLMs generate tokens based on maximum likelihood, not factual knowledge. Lowering temperature (e.g. 0.0 - 0.2) reduces sampling entropy. RAG grounds response in retrieved facts. System prompt instructs model to say \'I do not have enough information\' if answer isn\'t in context.',
