                                                                        'questions' => [
                                        [
                                            'text' => 'How do Rerankers (Cross-Encoders vs Bi-Encoders, e.g. Cohere Rerank / BGE-Reranker) improve RAG retrieval quality? Why is two-stage retrieval (Bi-encoder retrieval -> Cross-encoder reranking) the industry standard?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Bi-encoders encode query and document independently (fast for indexing millions of vectors via vector DB). Cross-encoders take (query, document) pair simultaneously through transformer attention layers (much more accurate, but slow). Two-stage: retrieve top-50 with Bi-encoder, rerank top-5 with Cross-encoder.',
                                        ],
                                        [
                                            'text' => 'Explain Hybrid Search: combining Dense Vector Search (semantic similarity) with Sparse Lexical Search (BM25 / SPLADE). How does Reciprocal Rank Fusion (RRF) merge ranking scores?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Dense search understands semantics (\'automobile\' ~ \'car\'), but fails on exact keyword codes/SKUs. BM25 excels at exact keyword matching. RRF combines rankings: `RRF_Score = sum(1 / (k + rank_i))` where k is a constant (e.g. 60), producing balanced retrieval.',
                                        ],
                                        [
                                            'text' => 'How does Structured Output generation work in LLMs (JSON Schema mode, Function Calling / Tool Calling)? How do libraries like Instructor or Outlines enforce strict JSON schema adherence at token generation time?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Function calling passes JSON schema in API request. Outlines / Grammar-based generation restricts the LLM\'s next-token logits mask using a finite state machine (FSM) compiled from the regex/JSON schema, guaranteeing 100% syntactically valid JSON output.',
                                        ],
                                        [
                                            'text' => 'How do you evaluate RAG systems using the Ragas or TruLens evaluation frameworks? Explain the RAG Triad: Context Relevance, Groundedness (Faithfulness), and Answer Relevance.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Context Relevance: are retrieved chunks relevant to query? Groundedness: is the LLM answer strictly derived from retrieved chunks without hallucination? Answer Relevance: does the answer directly address the user\'s question? Evaluated using LLM-as-a-judge.',
                                        ],
