                                            'text' => 'How do you implement semantic caching in LLM applications using GPTCache or Redis Vector Similarity to reduce API costs and latency?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Incoming query is embedded into vector. Search Redis for past cached queries with cosine similarity > threshold (e.g. 0.92). If match found, return cached response immediately, slashing latency from 3s to 20ms and saving API tokens.',
                                        ],
