                                        [
                                            'text' => 'How do you build an Autonomous Agent workflow using LangGraph or AutoGen? Explain StateGraph, agent nodes, edges, conditional routing, and human-in-the-loop approvals.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'LangGraph models agent execution as a state machine graph. Nodes represent LLMs or tool functions. Conditional edges evaluate node output to determine next step (e.g. retry tool, ask user, finish). State is persisted in checkpointer, enabling human-in-the-loop pauses.',
                                        ],
                                        [
                                            'text' => 'How do you protect LLM applications against Prompt Injection attacks (Direct Injection, Indirect Injection via retrieved documents, and System Prompt Leaks)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Direct injection overrides system instructions (`Ignore previous instructions and...`). Indirect injection embeds malicious instructions in RAG documents/webpages. Mitigate with input guardrails (NeMo Guardrails, Llama Guard), strict system prompt boundaries (delimiters), and read-only tool privileges.',
                                        ],
                                        [
                                            'text' => 'How do you optimize LLM streaming latency (Time-to-First-Token - TTFT) and throughput (Tokens-Per-Second - TPS) in production using vLLM, TensorRT-LLM, or HuggingFace TGI?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'vLLM uses PagedAttention to eliminate memory fragmentation in Key-Value (KV) cache, enabling continuous batching. Continuous batching inserts new requests into active forward passes dynamically without waiting for full sequence completions.',
