                                            'note' => 'LiteLLM provides unified OpenAI-compatible interface across 100+ LLMs. Tracks tokens per user/team, enforces TPM (Tokens Per Minute) / RPM rate limits in Redis, and automatically fails over to backup model (e.g. Anthropic) if primary provider returns HTTP 500/429.',
                                        ],
