                                        [
                                            'text' => 'Deep dive into Transformer Attention Mechanism: Scaled Dot-Product Attention, Multi-Head Attention (MHA), Multi-Query Attention (MQA), and Grouped-Query Attention (GQA). Why does GQA dominate modern LLMs like LLaMA 3?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'MHA has N key, value, and query heads (heavy KV cache memory). MQA shares 1 KV head across all query heads (fast, but small quality loss). GQA groups query heads (e.g. 8 query heads share 1 KV head), balancing low memory footprint with high representational capacity.',
                                        ],
                                        [
                                            'text' => 'Explain Advanced RAG patterns: Query Rewriting, HyDE (Hypothetical Document Embeddings), and Step-Back Prompting. How do they resolve vocabulary mismatch and ambiguous user queries?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'HyDE uses LLM to generate a hypothetical answer first, then embeds that hypothetical document to search vector DB (matches document-to-document embedding space instead of short-query-to-document). Step-back prompting abstracts specific queries into high-level concepts.',
                                        ],
                                        [
                                            'text' => 'How does Quantization work in LLMs (GPTQ, AWQ, GGUF / llama.cpp, bitsandbytes 4-bit/8-bit)? What are the trade-offs between activation outliers, perplexity loss, and VRAM memory footprint?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Quantization reduces FP16/BF16 weights to INT8 or INT4. AWQ (Activation-aware Weight Quantization) protects the 1% most salient weight channels based on activation magnitudes, achieving near-lossless INT4 compression and cutting VRAM by 70%.',
                                        ],
                                        [
                                            'text' => 'Explain the Key-Value (KV) Cache in LLM inference. How does PagedAttention (vLLM) solve memory fragmentation and enable dynamic KV cache memory allocation like OS virtual memory paging?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'During autoregressive generation, past tokens\' Key and Value matrices are cached to avoid recomputing attention. Traditional KV cache allocates static contiguous memory for max context length, causing 60-80% memory waste. PagedAttention partitions KV cache into non-contiguous blocks, eliminating internal fragmentation.',
                                        ],
