                                            'text' => 'What are Rotary Position Embeddings (RoPE) and Context Length Extension methods (YaRN, LongLoRA, Position Interpolation)? How do they allow models trained on 4K tokens to extrapolate to 128K tokens?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'RoPE encodes relative position by multiplying representations by a rotation matrix. Position Interpolation scales down position indices to fit within original training window. YaRN applies frequency-dependent temperature scaling to attention logits, preventing catastrophic attention dispersion.',
                                        ],
