                                            'note' => 'Self-RAG trains model to generate special reflection tokens (`[Retrieve]`, `[IsRel]`, `[IsSup]`). CRAG evaluates retrieval quality with a retrieval evaluator: if relevant -> generates answer; if ambiguous -> web search fallback; if irrelevant -> strips context and falls back to model knowledge.',
