                                    'title' => 'Set 1: Core Foundations & Runtime Architecture',
                                    'duration_minutes' => 15,
                                    'description' => 'Essential foundational questions: language lifecycle, runtime internals, memory model, and typing.',
                                    'tags' => [
                                        'llm_rag',
                                        'ai_ml',
