                                        'foundations',
                                    ],
                                                                        'questions' => [
                                        [
                                            'text' => 'Deep dive into FlashAttention-2 and FlashAttention-3: How does tiling, online softmax, and GPU SRAM memory hierarchy optimization achieve O(N) memory complexity and 3x-8x speedups over standard attention?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Standard attention materializes N x N attention matrix in slow GPU High Bandwidth Memory (HBM), causing memory bottleneck O(N^2). FlashAttention splits Q, K, V into blocks, loads into fast on-chip SRAM, computes softmax incrementally (online softmax), and avoids writing N x N intermediate matrix to HBM.',
                                        ],
                                        [
                                            'text' => 'Explain Direct Preference Optimization (DPO) versus Reinforcement Learning from Human Feedback (RLHF with PPO). Why does DPO eliminate the need for training an explicit reward model?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'RLHF with PPO trains a reward model and uses complex actor-critic RL optimization (unstable, high VRAM). DPO mathematically reparameterizes the reward function using the policy model directly: loss optimizes implicit reward via cross-entropy on preferred vs rejected completions relative to reference model.',
                                        ],
                                        [
                                            'text' => 'How does Parameter-Efficient Fine-Tuning (PEFT) with LoRA (Low-Rank Adaptation) and QLoRA work under the hood? Explain low-rank matrix decomposition ($W + B 	imes A$) and Double Quantization (NF4).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'LoRA freezes original weight $W_{d 	imes k}$ and injects trainable low-rank decomposition $B_{d 	imes r} 	imes A_{r 	imes k}$ where rank $r \\ll d$ (e.g. $r=16$), reducing trainable parameters by 99%. QLoRA quantizes base model to 4-bit NormalFloat (NF4), dequantizes during forward pass, allowing fine-tuning 70B models on a single GPU.',
                                        ],
                                        [
                                            'text' => 'Explain Mixture of Experts (MoE) architecture (e.g. Mixtral 8x7B, DeepSeek). How do Router/Gating networks route tokens to top-k experts, and how does load balancing loss prevent expert collapse?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Replaces feedforward network (FFN) with multiple independent expert FFNs. Router network computes softmax over expert affinities and routes each token to top-2 experts. Auxiliary load balancing loss penalizes over-utilization of popular experts, ensuring all experts receive balanced training gradients.',
                                        ],
                                        [
                                            'text' => 'How does Continuous Pre-training on domain-specific corpora differ from Fine-Tuning? How do you prevent Catastrophic Forgetting during domain adaptation of open-weights models?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Continuous pre-training trains on billions of raw domain tokens using causal language modeling loss. Mitigate catastrophic forgetting by replay mixing: blend 5-10% general-domain dataset (e.g. SlimPajama) with domain tokens, use learning rate warmup and decay, and freeze early layers.',
                                        ],
                                    ],
                                ],
                                [
