                                        'implementation',
                                    ],
                                                                        'questions' => [
                                        [
                                            'text' => 'Architect a multi-agent autonomous software engineering system (similar to Devin or SWE-agent) with sandbox code execution, AST code inspection, test execution feedback loops, and Git version control.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Coordinator agent breaks issue into subtasks. Coder agent generates code and diffs. Secure Docker/gVisor sandbox executes tests and linters. If tests fail, execution output is fed back into agent context for iterative bug-fixing until all unit tests pass before creating pull request.',
                                        ],
                                        [
                                            'text' => 'How do you design a high-throughput, distributed vector retrieval infrastructure capable of searching 1 Billion vectors under 20ms p99 latency across distributed shards with replication?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Partition vectors across distributed shards using consistent hashing. Each shard maintains an in-memory HNSW index with Product Quantization (PQ) to compress vector dimensions. Query coordinator fans out query to all shards in parallel, aggregates candidate top-K, and performs exact rerank on centroid candidates.',
                                        ],
                                        [
                                            'text' => 'Design a resilient fallback and routing mesh across multiple self-hosted vLLM clusters and commercial APIs (OpenAI / Anthropic) with semantic routing based on query complexity.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Small classifier / embedding model inspects incoming query complexity. Simple factual queries route to fast local 8B model (vLLM). Complex multi-step reasoning queries route to frontier models (Claude 3.5 Sonnet). If local cluster is saturated (queue length > threshold), route overflow to cloud APIs.',
                                        ],
                                        [
                                            'text' => 'How do you implement Privacy-Preserving LLM Inference and RAG with Differential Privacy, Homomorphic Encryption, or Zero-Knowledge Proofs for confidential healthcare/banking data?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Apply differential privacy noise during embedding generation to prevent reconstruction attacks. Confidential computing using AMD SEV-SNP / AWS Nitro Enclaves ensures memory encryption during model execution, preventing even hypervisor/cloud provider access.',
                                        ],
                                        [
                                            'text' => 'How do you architect an automated LLM Red-Teaming and Adversarial Vulnerability Testing engine that generates automated jailbreaks, multi-turn deceptive prompts, and prompt injection probes?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Use an attacker LLM model (Pair-wise Automated Red-teaming) that iteratively crafts adversarial prompts, evaluates target response, and optimizes prompt perturbation based on attack success score until jailbreak succeeds or guardrail proves robust.',
                                        ],
                                    ],
                                ],
