                                                                        'questions' => [
                                        [
                                            'text' => 'Conduct a production post-mortem: An enterprise customer-facing RAG assistant generated a high-severity hallucination citing a fabricated company policy, resulting in legal liability. Root-cause analysis revealed vector chunk fragmentation and silent Cross-Encoder threshold bypass. How do you re-architect the pipeline to guarantee verified factual citations?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Implement strict Sentence-Window retrieval or Parent-Document retrieval (search small chunks for accuracy, retrieve full parent document for context). Enforce programmatic citation verification: verify that every claim in generated answer has an exact textual substring match in source document before returning to client.',
                                        ],
                                        [
                                            'text' => 'How do you architect an enterprise disaster recovery and multi-region failover strategy for an AI platform serving 50 million tokens/hour across multiple GPU clusters (NVIDIA H100s)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Replicate model weights in regional S3 buckets with NVMe caching. Active-active Ray Serve or Kubernetes vLLM clusters across regions. Global load balancer routes requests based on real-time GPU queue depth. Automatic fallback to commercial cloud APIs during GPU outage.',
                                        ],
                                        [
                                            'text' => 'How do you conduct Chaos Engineering on an LLM inference mesh? Walk through simulating GPU memory exhaustion (CUDA OOM), KV cache eviction cascades, and network partition between vector database and LLM workers.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Flood cluster with maximum-length context prompts to trigger KV cache eviction. Verify continuous batching engine handles preemption without crashing workers. Cut network to vector DB to verify application returns graceful degraded answer from model base weights instead of crashing.',
                                        ],
                                        [
                                            'text' => 'Design a zero-trust enterprise architecture for LLM Tool Execution: sandbox isolation (gVisor/Firecracker microVMs), cryptographic token authentication, and capability-based security.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Every tool invocation runs in ephemeral Firecracker microVM with no network access (or strictly whitelisted outbound proxies). Tool capabilities are bounded by cryptographic capabilities tokens signed with short expiration. System operations drop all Linux capabilities (`CAP_SYS_ADMIN`).',
                                        ],
                                        [
                                            'text' => 'How do you architect a Continuous Learning pipeline for LLMs that ingests daily enterprise support transcripts, extracts golden Q&A pairs via synthetic curation, and fine-tunes models on a recurring weekly schedule?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
