                                        [
                                            'text' => 'Explain the PyTorch Dynamic Computational Graph (Autograd). How does forward execution build the Directed Acyclic Graph (DAG) of Tensor operations, and how does `.backward()` traverse the graph to compute gradients via reverse-mode automatic differentiation?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Tensors with `requires_grad=True` track operations via `grad_fn`. Forward pass dynamically creates DAG of Function nodes. `.backward()` executes chain rule starting from output scalar, traversing in reverse topological order, accumulating gradients into `.grad` attributes, and discarding intermediate graph unless `retain_graph=True`.',
                                        ],
                                        [
                                            'text' => 'How does PyTorch handle GPU Memory Management (CUDA allocator)? What is the difference between allocated memory (`torch.cuda.memory_allocated()`) and reserved cached memory (`torch.cuda.memory_reserved()`), and how do you prevent CUDA Out of Memory (OOM) errors?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'PyTorch uses a caching allocator to avoid expensive `cudaMalloc` calls; freed tensor memory is retained in pool for future allocations. OOM occurs when largest contiguous block in reserved pool cannot satisfy allocation. Mitigate using `torch.cuda.empty_cache()`, gradient checkpointing, smaller batch sizes, or mixed precision.',
                                        ],
                                        [
                                            'text' => 'Explain PyTorch `DataLoader` and `Dataset` architecture. How do `num_workers`, `pin_memory=True`, and `collate_fn` optimize data transfer throughput from CPU host RAM to GPU VRAM?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`num_workers > 0` spawns multi-process data prefetching. `pin_memory=True` allocates tensors in page-locked (pinned) CPU host memory, enabling asynchronous DMA (Direct Memory Access) transfers to GPU via `non_blocking=True`. Custom `collate_fn` handles variable-length sequence padding.',
                                        ],
                                        [
                                            'text' => 'Compare activation functions in Deep Learning: ReLU, Leaky ReLU, GELU (Gaussian Error Linear Unit), and SwiGLU. Why has GELU replaced ReLU as the standard in modern Transformer architectures?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'ReLU has dead neuron problem (zero gradient for negative inputs). GELU weighs inputs by their percentile in standard Gaussian distribution, providing smooth non-linear probabilistic gating with non-zero gradient everywhere, stabilizing transformer self-attention training.',
                                        ],
                                        [
                                            'text' => 'What are Vanishing and Exploding Gradients in deep neural networks? How do proper weight initialization (He/Kaiming, Xavier/Glorot), residual connections, and gradient clipping (`torch.nn.utils.clip_grad_norm_`) mitigate them?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Repeated matrix multiplications during backpropagation cause gradients to shrink to zero or grow exponentially. Xavier scales weights based on fan_in/fan_out for tanh; Kaiming accounts for ReLU zeroing half of activations. Residual shortcuts ($x + F(x)$) provide identity gradient highways. Gradient clipping caps L2 norm.',
                                        ],
