                                        [
                                            'text' => 'How does Mixed Precision Training (`torch.cuda.amp.autocast` and `GradScaler`) work in PyTorch? Why is gradient scaling necessary to prevent gradient underflow when backpropagating in FP16 or BF16?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`autocast()` automatically casts forward ops to FP16/BF16 where safe (e.g. matrix multiplication). In FP16, small gradients underflow to zero. `GradScaler` multiplies loss by scale factor before backward pass, computes gradients, unscales them before optimizer step, and skips update if Inf/NaN detected.',
                                        ],
                                        [
                                            'text' => 'Explain Normalization techniques: Batch Normalization (BatchNorm), Layer Normalization (LayerNorm), and RMSNorm (Root Mean Square Normalization). Why is LayerNorm preferred over BatchNorm in Transformers and NLP?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'BatchNorm normalizes across batch dimension for each channel (depends on batch size, fails with small batches or variable-length sequences). LayerNorm normalizes across feature dimensions independently for each sample, making it invariant to batch size. RMSNorm simplifies LayerNorm by scaling only by root mean square without subtracting mean.',
                                        ],
                                        [
                                            'text' => 'How do you implement custom PyTorch autograd functions by subclassing `torch.autograd.Function`? Explain the static `forward(ctx, ...)` and `backward(ctx, ...)` methods and saving tensors via `ctx.save_for_backward()`.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Define static methods `forward(ctx, x)` and `backward(ctx, grad_output)`. Store intermediate activation tensors via `ctx.save_for_backward()`. In `backward()`, retrieve saved tensors with `ctx.saved_tensors` and compute vector-Jacobian products (VJP) with respect to each input.',
                                        ],
                                        [
                                            'text' => 'Compare Deep Learning Optimizers: SGD with Momentum, Adam, AdamW (weight decay decoupled from gradient updates), and Lion. Why did AdamW fix the weight decay flaw in original Adam?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'In standard Adam with L2 regularization, weight decay is added directly to gradients, which gets scaled down by running variance $v_t$, disproportionately penalizing frequently updated weights. AdamW decouples weight decay, applying decay directly to parameter weights after step.',
                                        ],
                                        [
                                            'text' => 'How do Learning Rate Schedulers work in PyTorch (Cosine Annealing with Warmup, OneCycleLR, ReduceLROnPlateau)? Why is warmup critical in early training epochs of deep networks?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Warmup linearly ramps learning rate from 0 to peak LR during initial epochs, preventing large volatile gradients from throwing randomly initialized weights into poor local minima. Cosine Annealing smoothly decays LR towards zero following half-cosine curve.',
                                        ],
                                    ],
