                                            'text' => 'How do you implement Gradient Accumulation in PyTorch to train with an effective batch size of 256 on a GPU that only fits a physical batch size of 16 in VRAM?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Divide loss by accumulation steps: `loss = loss / accum_steps; loss.backward()`. Repeat for N mini-batches (gradients accumulate in `.grad`). On every Nth step, call `optimizer.step()` and `optimizer.zero_grad()`, effectively simulating an N-times larger batch.',
                                        ],
