                                            'note' => 'Save dictionary: `{\'epoch\': epoch, \'model_state_dict\': model.state_dict(), \'optimizer_state_dict\': optimizer.state_dict(), \'scaler_state_dict\': scaler.state_dict()}`. Saving only model weights loses optimizer momentum and learning rate state, corrupting resumed training.',
