                                            'text' => 'Deep dive into Distributed Data Parallel (DDP - `torch.nn.parallel.DistributedDataParallel`) versus DataParallel (DP). Why does DDP run multi-process without GIL contention, and how does Ring-AllReduce synchronize gradients?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'DP uses single process with multithreading (bottlenecked by GIL and primary GPU parameter scatter/gather). DDP spawns 1 process per GPU (`torchrun`). During backward pass, DDP communicates gradients using NCCL Ring-AllReduce concurrently with backward computation, achieving near-linear scaling across multi-node clusters.',
                                        ],
                                        [
                                            'text' => 'Explain Fully Sharded Data Parallel (FSDP - ZeRO-3 equivalent) in PyTorch. How does FSDP shard optimizer states, gradients, and model parameters across GPUs to train models larger than a single GPU\'s VRAM?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'ZeRO-1 shards optimizer states. ZeRO-2 shards gradients. ZeRO-3 (FSDP) shards model parameters as well. During forward pass, FSDP all-gathers parameters for current layer, computes forward, and frees un-sharded weights immediately before moving to next layer.',
                                        ],
                                        [
                                            'text' => 'How does Gradient Checkpointing (`torch.utils.checkpoint`) trade compute for memory? What is the mathematical reduction in activation memory during training of deep networks?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Instead of storing all forward activations in VRAM for backward pass, gradient checkpointing discards intermediate activations and recomputes them on-the-fly during the backward pass. Reduces activation memory from $O(N)$ to $O(\\sqrt{N})$ at cost of ~20-30% extra compute time.',
                                        ],
                                        [
                                            'text' => 'Explain `torch.compile` (PyTorch 2.0+ architecture): TorchDynamo, AOTAutograd, PrimTorch, and TorchInductor. How does kernel fusion and loop fusion in TorchInductor eliminate GPU memory round-trips?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'TorchDynamo intercepts Python frame evaluation via CPython API, extracting FX graphs while falling back gracefully on unsupported Python code. AOTAutograd generates backward graph ahead of time. TorchInductor compiles FX graph into fused C++/Triton GPU kernels, fusing elementwise ops into single GPU memory read/write.',
                                        ],
