                                            'note' => 'CUDA stream is a queue of GPU operations that execute in order. Operations in different streams execute concurrently on GPU. Use `torch.cuda.Stream()`. Synchronize streams using `event.record()` and `stream.wait_event(event)`. Default stream blocks CPU unless using non-default streams.',
                                        ],
