                                            'note' => 'Unstructured pruning zeros individual weights (sparse, requires specialized hardware). Structured pruning removes entire channels/heads (runs on standard hardware). QAT models quantization error during training via fake-quantize modules, learning weights that survive INT8 conversion with minimal accuracy loss.',
