                                                                        'questions' => [
                                        [
                                            'text' => 'Deep dive into 3D Parallelism for Large Language Models: Tensor Parallelism (Megatron-LM), Pipeline Parallelism (1F1B schedule), and Data Parallelism (ZeRO-3/FSDP). How do they compose together to train 100B+ parameter models across thousands of GPUs?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Tensor Parallel splits individual weight matrices (column/row parallel in self-attention) across GPUs within a single NVLink server node. Pipeline Parallel partitions layers across nodes, executing in 1F1B (one-forward-one-backward) micro-batches to minimize pipeline bubbles. Data Parallelism / FSDP shards remaining replicas across the cluster.',
                                        ],
                                        [
                                            'text' => 'Explain the mathematical formulation of FlashAttention: Online Softmax across tiled blocks. Walk through the forward and backward derivation showing how gradients are recomputed in SRAM without storing the $N 	imes N$ attention probability matrix.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Online softmax maintains running max $m_i$ and running sum $l_i$ across blocks, updating scaling factor dynamically: $l_i = l_{i-1} e^{m_{i-1}-m_i} + \\sum e^{S_{ij}-m_i}$. In backward pass, FlashAttention recomputes attention logits $S = Q K^T$ directly from stored $Q, K, V$ in SRAM blocks, avoiding HBM reads.',
                                        ],
                                        [
                                            'text' => 'How does PyTorch handle Custom C++ / CUDA Extension compilation (`torch.utils.cpp_extension`)? Explain PyBind11 bindings, ATen tensor library (`at::Tensor`), and dispatching based on tensor device and scalar type (`AT_DISPATCH_FLOATING_TYPES`).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Build extensions using `load` (JIT) or `setup.py` (AOT). C++ wrapper extracts tensor data pointers using `tensor.data_ptr<float>()`. `AT_DISPATCH_FLOATING_TYPES` generates specialized template code for float32, float64, and FP16, launching the underlying raw CUDA kernel with dynamic grid/block dimensions.',
                                        ],
                                        [
                                            'text' => 'Explain the mechanics of Asynchronous Distributed Data Parallelism: Parameter Servers versus AllReduce. Why does AllReduce bandwidth optimality depend on Ring and Tree algorithms across differing network topologies?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Parameter server has single-node bottleneck. In Ring-AllReduce, each GPU sends and receives $2(N-1)/N 	imes S$ bytes in $2(N-1)$ steps, independent of total GPU count (bandwidth-optimal). Tree-AllReduce (Double Binary Tree) minimizes latency steps for small tensor sizes across thousands of nodes.',
                                        ],
                                        [
                                            'text' => 'How does PyTorch memory fragmentation occur at the operating system virtual memory level? Explain `expandable_segments:True` in `PYTORCH_CUDA_ALLOC_CONF` and its impact on large-model training.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Virtual memory fragmentation occurs when allocations and deallocations leave holes in contiguous virtual address space, failing large allocations even when total free memory is sufficient. Setting `expandable_segments:True` uses `cuMemMap` driver APIs to allocate non-contiguous physical pages into contiguous virtual addresses, eliminating fragmentation.',
                                        ],
                                    ],
                                ],
                                [
                                    'id' => 'ai_ml-deeplearning_pytorch-s3-set2',
