                                                                        'questions' => [
                                        [
                                            'text' => 'Architect an ultra-large-scale Deep Learning Recommendation Model (DLRM) in PyTorch processing 100 Million Sparse Embedding lookups per second across multi-GPU nodes with embedding table sharding (TorchRec).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'DLRM combines sparse embedding tables (terabytes in size) with dense dense features (MLP). TorchRec shards embedding tables across GPUs using table-wise or column-wise partitioning. Uses All-to-All collective communication to exchange pooled embeddings across nodes before dense MLP interaction layers.',
                                        ],
                                        [
                                            'text' => 'Design a resilient continuous training pipeline for autonomous driving or computer vision models that continuously ingests fleet edge data, identifies hard negatives using active learning, and triggers distributed retraining with zero human intervention.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Edge models trigger data upload on high uncertainty (low entropy confidence). Active learning pipeline ranks samples, labels via automated pseudo-labeling and human validation, and updates training dataset. Triggers automated Kubeflow training pipeline, validating against regression benchmark before OTA deployment.',
                                        ],
                                        [
                                            'text' => 'How do you architect a multi-modal diffusion model training and inference pipeline (like Stable Diffusion / Flux) in PyTorch with text conditioning (T5/CLIP text encoders), VAE latent space compression, and Denoising Score Matching?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'VAE encoder compresses $512 	imes 512$ RGB image into $64 	imes 64$ latent representation (8x spatial reduction, 64x memory saving). Forward process adds Gaussian noise according to scheduler. U-Net / Diffusion Transformer (DiT) with cross-attention predicts added noise conditioned on CLIP/T5 text embeddings using MSE loss.',
                                        ],
                                        [
                                            'text' => 'How do you implement Hardware-Aware Neural Architecture Search (NAS) in PyTorch using differentiable architecture search (DARTS) or reinforcement learning to find optimal subnetworks for target edge devices (Apple Neural Engine / Qualcomm NPU)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'DARTS relaxes discrete architecture search space to continuous probability distribution over candidate operations (conv $3 	imes 3$, conv $5 	imes 5$, skip connection). Bi-level optimization trains network weights and architecture parameters concurrently, with a hardware latency loss penalty measured on physical edge device.',
                                        ],
                                        [
                                            'text' => 'How do you design a fault-tolerant distributed training framework in PyTorch that survives node failures without restarting the training run from the last hourly checkpoint (Elastic Training / TorchElastic)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'TorchElastic (`torchrun`) uses etcd/consul rendezvous backend. When a worker node crashes, remaining nodes pause, re-rendezvous, dynamically scale world size from N to N-1, restore state from in-memory distributed checkpointing or shared NVMe, and resume training within 30 seconds.',
                                        ],
                                    ],
