                                                                        'questions' => [
                                        [
                                            'text' => 'Conduct a production post-mortem: A 3-week distributed training run on 512 GPUs experienced loss divergence (NaN loss) at step 45,000. Checkpoint inspection revealed activation explosion in attention projection layers. How do you analyze gradient norms, restore from an earlier healthy checkpoint, and implement QK-Norm or Z-loss to prevent recurrence?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Attention logits ($QK^T / \\sqrt{d}$) drift large in deep networks, causing softmax saturation and unstable backward gradients. Apply QK-Norm (LayerNorm applied directly to Query and Key tensors before dot product). Add auxiliary Z-loss ($\\log^2 \\sum e^{z_i}$) to penalize large partition functions, stabilizing attention logits.',
                                        ],
                                        [
                                            'text' => 'How do you architect an enterprise disaster recovery and multi-region checkpoint replication system for multi-million-dollar AI training clusters?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Write asynchronous distributed checkpoints using PyTorch Distributed Checkpoint (DCP) directly to local NVMe, while background daemon streams chunks to AWS S3 with cross-region replication to standby GPU cluster. Checkpoint write time drops from 10 minutes (blocking) to <5 seconds.',
                                        ],
                                        [
                                            'text' => 'How do you conduct automated Chaos Testing on a 100-node GPU cluster during PyTorch DDP training? Walk through simulating InfiniBand link degradation, silent data corruption, and GPU ECC memory errors.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Inject network packet drops on inter-switch links to verify NCCL watchdog timeout (`NCCL_ASYNC_ERROR_HANDLING=1`). Simulate single GPU slowdown to verify straggler mitigation. Induce ECC single-bit errors via `nvidia-smi` to verify GPU driver catches memory corruption without silent weight poisoning.',
                                        ],
                                        [
                                            'text' => 'Design a zero-trust model governance and cryptographic provenance framework for PyTorch models: cryptographic model signing, weight tampering detection, and SBOM (Software Bill of Materials) verification.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Avoid `torch.save` / `pickle` (vulnerable to arbitrary code execution / RCE). Serialize models exclusively using Safetensors. Sign Safetensors weight files with Sigstore / Cosign cryptographic key pairs. Inference servers verify signature and verify training provenance metadata before loading into GPU.',
                                        ],
                                        [
                                            'text' => 'How do you architect an automated hyperparameter optimization (HPO) engine in PyTorch using Optuna with Hyperband / ASHA (Asynchronous Successive Halving Algorithm) pruning on distributed GPU clusters?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Optuna uses Tree-structured Parzen Estimator (TPE) for Bayesian optimization. ASHA pruning evaluates learning curves at early epochs, aggressively terminating unpromising trials (bottom 75%) to reallocate GPU compute to top-performing hyperparameter configurations, achieving 10x speedup over grid search.',
                                        ],
                                    ],
