                                                                        'questions' => [
                                        [
                                            'text' => 'Explain the Linux kernel primitives underpinning Docker containers: Namespaces (pid, net, ipc, mnt, uts, user) and Control Groups (cgroups v1/v2). How do they provide process isolation and resource limitation?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Namespaces provide isolation: determine what a process can see (own PID tree, network interfaces, mount points). Cgroups provide resource accounting and limitation: determine what a process can use (CPU shares, memory limits, I/O bandwidth). Containers are isolated Linux processes, not VMs.',
                                        ],
                                        [
                                            'text' => 'Explain Docker image layer architecture (UnionFS / OverlayFS). How do layer caching, the copy-on-write (CoW) mechanism, and multi-stage Dockerfiles optimize build speed and minimize image size?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Docker images are stacks of read-only layers with a thin writable container layer on top via Overlay2. Order Dockerfile instructions from least-frequently changed to most-frequently changed to maximize build cache. Multi-stage builds compile artifacts in build container and copy only binary to final lean runtime container.',
                                        ],
                                        [
                                            'text' => 'Explain the core Kubernetes Control Plane components: API Server (`kube-apiserver`), etcd, Scheduler (`kube-scheduler`), and Controller Manager (`kube-controller-manager`). How does declarative reconciliation work?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'API Server is the stateless gateway. etcd is the distributed key-value store holding cluster state. Scheduler binds unscheduled pods to nodes. Controller Manager runs control loops comparing actual state against desired state, making mutations until actual state matches desired state.',
                                        ],
                                        [
                                            'text' => 'What are the core Kubernetes Node components: `kubelet`, `kube-proxy`, and Container Runtime (containerd / CRI-O)? How does `kubelet` communicate with container runtimes via the Container Runtime Interface (CRI)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`kubelet` is the primary node agent watching PodSpecs from API server and instructing runtime via gRPC CRI to create/stop containers. `kube-proxy` maintains network rules (iptables / IPVS) on host for Service routing. containerd manages container lifecycle.',
                                        ],
                                        [
                                            'text' => 'Explain Kubernetes Pod lifecycle, phases (Pending, Running, Succeeded, Failed), and container states. What are Init Containers, and how do they differ from application containers?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Init containers run sequentially to completion before any app containers start. If an init container fails, pod restarts until it succeeds. Used for setup tasks (database migration, waiting for dependent service to be healthy, populating configuration files into shared volume).',
                                        ],
