                                        [
                                            'text' => 'Explain Kubernetes Service types: ClusterIP, NodePort, LoadBalancer, and ExternalName. How does `kube-proxy` use iptables or IPVS to route traffic to backing Pod endpoints?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'ClusterIP: internal virtual IP. NodePort: exposes port on every node IP. LoadBalancer: provisions cloud load balancer. ExternalName: CNAME alias. `kube-proxy` watches Service and Endpoints, writing iptables rules (or IPVS hash tables) that perform DNAT to randomly distribute packets to pod IPs.',
                                        ],
                                        [
                                            'text' => 'Compare Kubernetes Health Probes: Startup Probe, Liveness Probe, and Readiness Probe. What happens when each probe fails, and why is an incorrect liveness probe dangerous?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Startup probe disables others until app initializes. Liveness probe checks if container is alive: failure kills and restarts container. Readiness probe checks if pod can accept traffic: failure removes pod IP from Service endpoints. Flawed liveness probe (e.g. checking slow DB) causes cascading crash loops!',
                                        ],
                                        [
                                            'text' => 'How does Kubernetes manage configuration and secrets: `ConfigMap` and `Secret`? How do you inject them as environment variables versus mounted volume files, and how do updates propagate?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Env vars are static: container must restart to see updated ConfigMap values. Mounted volume files (`/etc/config`) are updated automatically by `kubelet` within a few minutes via atomic symlink swaps, allowing applications with file watchers to reload configuration without restart.',
                                        ],
                                        [
                                            'text' => 'Explain Kubernetes Persistent Volumes (PV), Persistent Volume Claims (PVC), and StorageClasses. How does dynamic storage provisioning work with CSI (Container Storage Interface) drivers?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'PVC is a user request for storage. StorageClass defines provisioner (e.g. AWS EBS CSI). When PVC is created, CSI driver calls cloud API to dynamically provision cloud disk (PV) and attaches volume to the host node where pod is scheduled.',
                                        ],
                                        [
                                            'text' => 'How do Kubernetes Deployments manage rolling updates (`RollingUpdate` strategy)? What are `maxSurge` and `maxUnavailable`, and how do you execute a zero-downtime rollback using `kubectl rollout undo`?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Deployment creates new ReplicaSet, scales it up while scaling old ReplicaSet down. `maxSurge` controls how many extra pods can be created above desired count; `maxUnavailable` controls how many pods can be down during rollout. `kubectl rollout undo` rolls back to previous ReplicaSet revision.',
                                        ],
                                    ],
