                                                                        'questions' => [
                                        [
                                            'text' => 'How do you configure Kubernetes Resource Requests and Limits (CPU and Memory)? What is CPU throttling (CFS quota), and what causes Out-Of-Memory (OOMKilled - Exit Code 137) container terminations?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Requests are used by scheduler for placement. Limits are enforced by cgroups. CPU limit sets Completely Fair Scheduler (CFS) quota: exceeding throttles CPU (slow execution, no crash). Memory limit is hard ceiling: exceeding triggers Linux OOM killer to terminate container with exit code 137.',
                                        ],
                                        [
                                            'text' => 'Explain Kubernetes Ingress and Ingress Controllers (e.g. NGINX Ingress, Traefik). How does Ingress route HTTP/HTTPS traffic to Services based on hostnames and URL path rules with TLS termination?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Ingress is an API resource defining routing rules. Ingress Controller (reverse proxy daemon) watches Ingress resources and dynamically updates NGINX/Envoy configuration. Terminates TLS using certificates stored in Kubernetes TLS Secrets, forwarding plain HTTP to backend pods.',
                                        ],
                                        [
                                            'text' => 'How do you manage container security in Docker and Kubernetes: non-root users (`USER 10001`), ReadOnlyRootFilesystem, and dropping Linux capabilities (`securityContext.capabilities.drop: [\'ALL\']`)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Never run as root. `runAsNonRoot: true` prevents container breakout exploits. `readOnlyRootFilesystem: true` prevents attackers from writing malware binaries to disk. Dropping all capabilities strips raw socket manipulation, network admin, and ptrace debugging privileges.',
                                        ],
                                        [
                                            'text' => 'Explain Horizontal Pod Autoscaler (HPA). How does HPA scale pod replicas based on CPU/Memory utilization from Metrics Server, and how do you configure custom metrics using Prometheus Adapter?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'HPA control loop queries Metrics Server or Custom Metrics API. Computes desired replicas: `desiredReplicas = ceil[currentReplicas * (currentMetricValue / targetMetricValue)]`. Prometheus Adapter translates Prometheus metrics (e.g. HTTP requests per second, queue length) into Kubernetes custom metrics for HPA.',
                                        ],
