                                            'text' => 'How do you troubleshoot a Kubernetes Pod stuck in `CrashLoopBackOff`, `ImagePullBackOff`, or `Pending` state using `kubectl describe pod`, `kubectl logs`, and events?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => '`Pending`: check events for insufficient CPU/memory or node selector/taint mismatch. `ImagePullBackOff`: verify image tag, registry authentication (`imagePullSecrets`), or rate limits. `CrashLoopBackOff`: check `kubectl logs --previous` to inspect container crash logs, exit code, or failed init containers.',
                                        ],
