                                        [
                                            'text' => 'Design a GitOps continuous deployment pipeline for Kubernetes using ArgoCD or Flux. How do GitOps reconciliation loops, declarative drift detection, and automated rollbacks work?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Git is the single source of truth. ArgoCD runs in-cluster controller comparing live cluster state against manifests in Git repository. When drift occurs (manual edit or git commit), controller automatically reconciles cluster to match Git. Rollback is as simple as `git revert`.',
                                        ],
                                        [
                                            'text' => 'How do you implement Progressive Delivery in Kubernetes using Argo Rollouts or Flagger with Canary deployments, automated metric analysis (Prometheus error rate < 1%), and automated rollback?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Argo Rollouts replaces Deployment with Rollout resource. Shifts traffic progressively (20% -> 40% -> 100%) using Service Mesh or Ingress. Runs automated metric analysis queries against Prometheus every minute: if error rate > 1% or latency > 500ms, aborts rollout and restores 100% traffic to stable version.',
                                        ],
                                        [
                                            'text' => 'How do you manage Kubernetes Secrets securely in enterprise production using external secret managers (HashiCorp Vault / AWS Secrets Manager) and External Secrets Operator (ESO)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Never store base64 secrets in Git. External Secrets Operator (ESO) watches `ExternalSecret` custom resource, authenticates to AWS Secrets Manager / Vault using pod IAM role, fetches secret value, and dynamically creates Kubernetes Secret in-memory.',
                                        ],
