                                            'duration_seconds' => 180,
                                            'note' => 'Istio mutates PodSpecs to inject Envoy sidecar proxy. Init container configures iptables to transparently redirect all pod inbound and outbound network traffic through Envoy. Proxies establish mutual TLS (mTLS) with cryptographically rotated certificates and inject W3C trace headers.',
                                        ],
                                        [
                                            'text' => 'How do you manage stateful workloads in Kubernetes using `StatefulSet` versus `Deployment`? Explain stable network identities (headless services), ordered creation/termination, and `volumeClaimTemplates`.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'StatefulSet gives pods ordinal names (`db-0`, `db-1`) that persist across restarts. Headless Service creates stable DNS A records for each pod (`db-0.db-service`). `volumeClaimTemplates` provisions a dedicated persistent disk for each ordinal replica that reattaches to the same ordinal pod if rescheduled.',
                                        ],
