                                            'note' => 'Deploy OpenTelemetry Collector as DaemonSet (node metrics, host logs) and Deployment (traces, app metrics). Apps export OTLP to collector. Collector forwards metrics to Prometheus, logs to Loki, and traces to Tempo. Grafana correlates trace ID to logs and metrics on a single dashboard.',
