                                                                        'questions' => [
                                        [
                                            'text' => 'Deep dive into Container Runtimes: OCI (Open Container Initiative) runtime-spec, runc, containerd, and low-level system calls (clone, setns, unshare, pivot_root). What happens from `docker run` to process execution?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Docker CLI calls containerd daemon via gRPC. Containerd pulls layers, sets up overlayfs rootfs. Spawns `runc` (OCI runtime). `runc` calls `clone` system call with namespace flags, mounts cgroups, calls `pivot_root` to change root filesystem, drops capabilities, and calls `execve` to start process.',
                                        ],
                                        [
                                            'text' => 'Explain the Linux kernel Completely Fair Scheduler (CFS) bandwidth control and its interaction with Kubernetes CPU limits. How do CFS quota periods (100ms) and millicores cause CPU throttling even when overall node CPU is at 20%?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Kubernetes CPU limit `500m` translates to CFS quota of 50ms per 100ms CFS period (`cpu.cfs_quota_us / cpu.cfs_period_us`). A multi-threaded process bursting across multiple CPU cores exhausts its 50ms quota in the first 10ms of the period, and is throttled by the OS kernel for the remaining 90ms!',
                                        ],
                                        [
                                            'text' => 'Explain Kubernetes API Server internals: HTTP request processing pipeline (Authentication, Authorization / RBAC, Mutating Admission Webhook, Schema Validation, Validating Admission Webhook, etcd write).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Request hits API server: 1. Authentication (X.509 cert, Bearer token). 2. Authorization (RBAC Role/ClusterRole check). 3. Mutating Webhooks (inject sidecars, defaults). 4. Schema validation. 5. Validating Webhooks (Gatekeeper/Kyverno policies). 6. Stored in etcd via transaction.',
                                        ],
                                        [
                                            'text' => 'How does Linux eBPF (Extended Berkeley Packet Filter) revolutionize Kubernetes networking and security (Cilium, Falco)? How does eBPF execute sandboxed bytecode directly inside the Linux kernel?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'eBPF attaches verified bytecode programs to kernel tracepoints, kprobes, and network sockets (XDP / tc). Executes inside kernel without context switching to userspace. Cilium bypasses iptables conntrack, handling service routing directly at socket layer; Falco inspects system calls for runtime threats in real time.',
                                        ],
                                        [
                                            'text' => 'How do Linux cgroups v2 differ from cgroups v1 in Kubernetes? Explain the unified hierarchy, pressure stall information (PSI), and improved memory controller behavior under memory pressure.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'cgroups v1 had fragmented independent hierarchies for cpu, memory, blkio. cgroups v2 unifies controllers into single tree. Eliminates deadlocks between memory and block I/O. Introduces Pressure Stall Information (PSI), measuring time processes spend starved for CPU, memory, and I/O.',
                                        ],
                                    ],
                                ],
                                [
                                    'id' => 'devops-docker_k8s-s3-set2',
                                    'series_number' => 3,
                                    'set_number' => 2,
                                    'title' => 'Set 2: Problem Solving & Scalable Implementation',
