                                                                        'questions' => [
                                        [
                                            'text' => 'Architect an ultra-high-availability multi-region Kubernetes infrastructure capable of surviving a complete cloud provider regional outage with zero downtime and automated Anycast DNS failover.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Independent Kubernetes clusters per cloud region (avoid cross-region control planes due to etcd latency limits). Cloudflare Anycast / Route53 ARC (Application Recovery Controller) routes traffic. Cross-region database replication (Spanner / CockroachDB / Aurora Global). GitOps synchronizes deployment state.',
                                        ],
                                        [
                                            'text' => 'Design a zero-trust runtime container security infrastructure using Falco, eBPF, and automated container isolation upon detecting anomalous system calls (e.g. reverse shell execution, `/etc/shadow` access).',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Falco monitors kernel system calls via eBPF probe. When suspicious event fires (e.g. `spawned_process_in_container`), Falco triggers gRPC event to security daemon. Daemon instantly isolates pod: applies quarantine NetworkPolicy, captures memory dump, and terminates pod.',
                                        ],
                                        [
                                            'text' => 'How do you architect a multi-tenant Kubernetes platform for 50 independent development teams using vCluster (virtual clusters), Hierarchical Namespaces (HNC), and resource quotas?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'vCluster creates fully isolated virtual Kubernetes control planes running as a StatefulSet inside a namespace on the host cluster. Teams have full `cluster-admin` inside their virtual cluster, create custom CRDs, while host cluster isolates compute and storage.',
                                        ],
                                        [
                                            'text' => 'Design a massive-scale Kubernetes cluster deployment running 5,000 nodes and 150,000 pods. What are the scaling bottlenecks in etcd, API Server serialization, kube-proxy, and IP allocation?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'etcd: separate event etcd from main etcd; use NVMe with high IOPS; increase defragmentation. API Server: enable P&F (API Priority and Fairness) to prevent control plane starvation. Kube-proxy: replace iptables with IPVS or Cilium eBPF to avoid O(N) packet rule evaluation.',
                                        ],
                                        [
                                            'text' => 'How do you implement confidential computing and container sandboxing in Kubernetes using Kata Containers (microVMs) or gVisor (application kernel) for untrusted customer code execution?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Standard containers share host Linux kernel. gVisor implements a userspace kernel (\'Sentry\') that intercepts all container system calls, isolating host. Kata Containers launches each pod inside a dedicated lightweight QEMU/Firecracker microVM with hardware virtualization.',
                                        ],
                                    ],
                                ],
                                [
                                    'id' => 'devops-docker_k8s-s3-set3',
                                    'series_number' => 3,
                                    'set_number' => 3,
                                    'title' => 'Set 3: Systems Design, Resilience & Edge Cases',
                                    'duration_minutes' => 15,
                                    'description' => 'Production engineering: fault tolerance, distributed state, rate limiting, and failure recovery.',
                                    'tags' => [
                                        'docker_k8s',
