                                        'systems',
                                    ],
                                                                        'questions' => [
                                        [
                                            'text' => 'Conduct a production post-mortem: A Kubernetes cluster experienced control plane failure where all nodes turned `NotReady` and `kubectl` timed out. Root cause analysis revealed etcd disk fsync latency exceeding 100ms and heartbeat timeouts. How do you triage, recover etcd quorum, and prevent recurrence?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'etcd requires disk fsync < 10ms. Shared disk I/O caused etcd leader to miss heartbeats, triggering continuous re-elections and cluster freeze. Recovery: stop etcd, isolate highest-revision member, re-initialize single-node cluster, re-add members. Prevention: dedicated high-IOPS NVMe SSDs (`fio` benchmark), separate event etcd.',
                                        ],
                                        [
                                            'text' => 'How do you architect a multi-region disaster recovery pipeline for a mission-critical Kubernetes deployment ensuring Recovery Point Objective (RPO) = 0 and Recovery Time Objective (RTO) < 60 seconds?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Synchronous database replication across low-latency zones. Cross-region asynchronous replication. Standby warm cluster running minimal replicas. Automated Route53 health check flips DNS to standby cluster within 30 seconds. HPA and Karpenter burst standby cluster to full capacity.',
                                        ],
                                        [
                                            'text' => 'How do you conduct automated Chaos Engineering on a production Kubernetes cluster using Chaos Mesh or LitmusChaos? Walk through simulating CoreDNS outages, node kernel panics, and cross-AZ network latency.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Simulate CoreDNS pod kill to verify NodeLocal DNSCache handles lookups. Inject 200ms latency between AZ1 and AZ2 to verify database replication and gRPC timeouts. Simulate node kernel panic to verify `kubelet` node lease expiration (40s) and pod eviction to healthy nodes.',
                                        ],
                                        [
                                            'text' => 'Design a zero-trust software supply chain security pipeline for Kubernetes: Sigstore (Cosign) image signing, In-toto attestation, Grype vulnerability scanning in admission control, and SLSA Level 3 compliance.',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'CI builds container with GitHub Actions (SLSA L3 provenance). Cosign signs container image using OIDC keyless signing. Kyverno admission controller verifies image signature against Sigstore public log before scheduling. Images with critical CVEs or missing signatures are rejected.',
                                        ],
                                        [
                                            'text' => 'How do you architect an automated, zero-downtime Kubernetes cluster upgrade strategy across 100 production nodes across major Kubernetes versions (e.g. v1.28 to v1.30)?',
                                            'category' => 'technical',
                                            'duration_seconds' => 180,
                                            'note' => 'Check API deprecations using Pluto/Kube-no-trouble. Upgrade control plane first. Upgrade worker nodes one-by-one using `kubectl drain --ignore-daemonsets --delete-emptydir-data`. Enforce PodDisruptionBudgets (PDB) so applications maintain minimum available replicas during node drains.',
                                        ],
                                    ],
                                ],
                            ],
